/* ---------- الدرس 20 ---------- */
{
    title: { ar: "Comprehensions والهياكل المتداخلة", en: "Comprehensions and nested structures" },
    body: {
        ar: `
<p>نمط شائع جداً في البرمجة: بناء قائمة جديدة بتطبيق عملية على كل عنصر من قائمة موجودة. الطريقة التقليدية تحتاج ثلاثة أسطر: إنشاء قائمة فارغة، حلقة <code>for</code>، ثم <code>append</code> داخلها. بايثون توفّر طريقة أقصر وأوضح تُسمّى <strong>List Comprehension</strong> تفعل نفس الشيء بسطر واحد.</p>

<h3>من حلقة تقليدية إلى Comprehension</h3>

<p>قارن: الطريقة التقليدية لبناء قائمة مربّعات الأرقام من 1 إلى 5 تحتاج حلقة كاملة. الصيغة المختصرة: <code>[x**2 for x in range(1, 6)]</code> — تُقرأ كالتالي: "لكل x في range، احسب x تربيع، وضعه في قائمة جديدة". النتيجة مطابقة تماماً، لكن بسطر واحد أوضح.</p>

<h3>إضافة شرط للـ Comprehension</h3>

<p>يمكن تصفية العناصر بإضافة <code>if</code> في النهاية: <code>[x for x in numbers if x % 2 == 0]</code> يُنشئ قائمة تحتوي فقط الأعداد الزوجية من numbers. هذا يدمج الفلترة والتحويل في سطر واحد بدل حلقة مع شرط داخلي.</p>

<h3>Dict Comprehension</h3>

<p>نفس الفكرة تنطبق على القواميس بصيغة مشابهة: <code>{k: v for k, v in ...}</code>. مثال عملي: تحويل قائمة أسماء إلى قاموس يخزّن طول كل اسم: <code>{name: len(name) for name in names}</code>.</p>

<h3>الهياكل المتداخلة (Nested Structures)</h3>

<p>في البرامج الحقيقية، تتداخل الهياكل: قائمة من القواميس (سجل طلاب مثلاً)، أو قاموس قيمه قوائم. الوصول يكون بسلسلة من الفهارس/المفاتيح: <code>students[0]["name"]</code> يعطي اسم الطالب الأول في قائمة قواميس. لا تخف من التداخل — تعامل معه خطوة بخطوة، مستوى تلو الآخر.</p>

<h3>أخطاء شائعة</h3>

<p>الإفراط في استخدام Comprehension حتى تصبح غير قابلة للقراءة — إن احتجت أكثر من شرط واحد أو منطقاً معقداً، الحلقة التقليدية أوضح وأفضل. القاعدة: إن لم تفهم السطر بنظرة واحدة، ارجع للحلقة العادية.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>List Comprehension: <code>[expr for item in iterable]</code> — أقصر من الحلقة التقليدية</li>
    <li>يمكن إضافة شرط: <code>[expr for item in iterable if condition]</code></li>
    <li>Dict Comprehension بنفس المنطق: <code>{k: v for k, v in ...}</code></li>
    <li>الهياكل المتداخلة تُقرأ خطوة بخطوة: <code>data[0]["key"]</code></li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>لديك قائمة أرقام من 1 إلى 20. استخدم List Comprehension لبناء قائمة جديدة تحتوي فقط مكعّبات الأرقام الزوجية منها (x**3 للأعداد الزوجية فقط) في سطر واحد.</p>
`,
        en: `<p>List comprehensions build a new list from an existing iterable in one line: [expr for item in iterable], optionally with a filter: [expr for item in iterable if condition]. The same pattern works for dicts. Nested structures (lists of dicts, etc.) are accessed step by step: data[0]["key"].</p>`
    },
    code: `<span class="cm"># الطريقة التقليدية</span>
<span class="kw">squares</span> = []
<span class="kw">for</span> x <span class="kw">in</span> <span class="fn">range</span>(1, 6):
    squares.append(x**2)
<span class="fn">print</span>(squares)


<span class="cm"># نفس الشيء بـ List Comprehension</span>
<span class="kw">squares2</span> = [x**2 <span class="kw">for</span> x <span class="kw">in</span> <span class="fn">range</span>(1, 6)]
<span class="fn">print</span>(squares2)          <span class="cm"># نفس النتيجة تماماً</span>


<span class="cm"># مع شرط: الأعداد الزوجية فقط</span>
<span class="kw">numbers</span> = [1, 2, 3, 4, 5, 6, 7, 8]
<span class="kw">evens</span> = [x <span class="kw">for</span> x <span class="kw">in</span> numbers <span class="kw">if</span> x % 2 == 0]
<span class="fn">print</span>(evens)             <span class="cm"># [2, 4, 6, 8]</span>


<span class="cm"># Dict Comprehension</span>
<span class="kw">names</span> = [<span class="st">"Sarah"</span>, <span class="st">"Ahmed"</span>, <span class="st">"Al"</span>]
<span class="kw">name_lengths</span> = {name: <span class="fn">len</span>(name) <span class="kw">for</span> name <span class="kw">in</span> names}
<span class="fn">print</span>(name_lengths)      <span class="cm"># {'Sarah': 5, 'Ahmed': 5, 'Al': 2}</span>


<span class="cm"># هياكل متداخلة: قائمة من القواميس</span>
<span class="kw">students</span> = [
    {<span class="st">"name"</span>: <span class="st">"Sarah"</span>, <span class="st">"grade"</span>: 95},
    {<span class="st">"name"</span>: <span class="st">"Ahmed"</span>, <span class="st">"grade"</span>: 88}
]
<span class="fn">print</span>(students[0][<span class="st">"name"</span>])     <span class="cm"># Sarah — أول طالب</span>
<span class="fn">print</span>(students[1][<span class="st">"grade"</span>])    <span class="cm"># 88 — درجة الثاني</span>`,
    quiz: {
        q: {
            ar: "أي تعبير يُنشئ قائمة بمكعّبات الأرقام الفردية فقط من numbers؟",
            en: "Which expression creates a list of cubes of only the odd numbers from numbers?"
        },
        options: {
            ar: [
                "[x**3 for x in numbers if x % 2 != 0]",
                "[x**3 for x in numbers]",
                "[x for x in numbers if x**3 % 2 != 0]",
                "{x**3 for x in numbers if x % 2 != 0}"
            ],
            en: [
                "[x**3 for x in numbers if x % 2 != 0]",
                "[x**3 for x in numbers]",
                "[x for x in numbers if x**3 % 2 != 0]",
                "{x**3 for x in numbers if x % 2 != 0}"
            ]
        },
        correct: 0,
        explanation: {
            ar: "الشرط if x % 2 != 0 يُصفّي الأرقام الفردية فقط قبل حساب المكعّب، والتعبير x**3 يحسب المكعّب لكل عنصر ناجٍ من الشرط، ضمن قوسين مربّعين لإنتاج قائمة.",
            en: "The condition if x % 2 != 0 filters only odd numbers before cubing, and x**3 computes the cube for each surviving element, inside square brackets to produce a list."
        }
    }
},

/* ---------- الدرس 21 — مشروع ---------- */
{
    title: { ar: "مشروع 3: دفتر جهات الاتصال", en: "Project 3: Contact book" },
    body: {
        ar: `
<p>مشروع هذا المستوى يجمع كل ما تعلمته: القوائم، القواميس، دوالهما، والتكرار عليها. ستبني دفتر جهات اتصال بسيطاً يعمل في الطرفية، يخزّن كل جهة اتصال كقاموس داخل قائمة كبرى.</p>

<h3>تصميم البيانات</h3>

<p>القرار الأهم قبل الكتابة: كيف تُمثَّل البيانات؟ كل جهة اتصال هي قاموس: <code>{"name": "...", "phone": "..."}</code>. ودفتر العناوين كاملاً هو قائمة من هذه القواميس: <code>contacts = []</code>. هذا التصميم (قائمة من قواميس) هو النمط الأكثر شيوعاً في البرمجة الحقيقية لتمثيل سجلات متعددة.</p>

<h3>حلقة القائمة الرئيسية</h3>

<p>البرنامج يحتاج حلقة <code>while True</code> تعرض قائمة خيارات (إضافة، بحث، عرض الكل، خروج) وتستمر حتى يختار المستخدم الخروج — نفس النمط الذي استخدمته في مشروع لعبة التخمين بالمستوى الثاني.</p>

<h3>البحث بحلقة for</h3>

<p>للبحث عن جهة اتصال بالاسم، مرّر بحلقة <code>for</code> على القائمة، وقارن اسم كل قاموس بما يبحث عنه المستخدم. استخدم <code>.lower()</code> على الطرفين لجعل البحث غير حسّاس لحالة الأحرف — تجربة مستخدم أفضل بكثير.</p>

<h3>لماذا قائمة قواميس وليس قاموساً واحداً كبيراً؟</h3>

<p>قد تتساءل: لماذا لا نستخدم قاموساً واحداً <code>{"Sarah": "0612345678"}</code> مباشرة؟ المشكلة أن هذا يفترض أن الاسم فريد دائماً، ويصعب تخزين بيانات إضافية (بريد، عنوان) لكل جهة اتصال بسهولة. قائمة القواميس أكثر مرونة وقابلية للتوسّع — نمط ستراه كثيراً في مشاريع حقيقية.</p>

<h3>تحديات للتوسيع</h3>

<ul>
    <li>أضف خيار حذف جهة اتصال بالاسم</li>
    <li>أضف خيار تعديل رقم هاتف جهة موجودة</li>
    <li>رتّب قائمة العرض أبجدياً بـ <code>sorted()</code> مع دالة key مناسبة</li>
    <li>امنع إضافة اسم مكرّر بالتحقق أولاً قبل append</li>
</ul>

<h3>ماذا أنجزت في هذا المستوى؟</h3>

<ul>
    <li>خزّنت مجموعات من البيانات بالقوائم وعدّلتها بدوالها المختلفة</li>
    <li>استخدمت Tuple للبيانات الثابتة وSet للعناصر الفريدة والعمليات عليها</li>
    <li>مثّلت بيانات ذات معنى بالقواميس بدل فهارس غامضة</li>
    <li>اختصرت حلقات التحويل والتصفية بـ Comprehensions</li>
    <li>وبنيت تطبيقاً كاملاً يجمع هذه الهياكل معاً في هيكل بيانات متداخل واقعي</li>
</ul>

<p>في المستوى الرابع سنتعلّم كيف نُنظّم الكود نفسه بالدوال (functions) — بدل تكرار نفس الأسطر، ستكتبها مرة واحدة وتستدعيها متى شئت.</p>
`,
        en: `<p>This project combines lists, dicts, and their methods into a working contact book: each contact is a dict inside a master list, with add/search/list/exit options in a main loop — the same list-of-dicts pattern used throughout real-world programs.</p>`
    },
    code: `<span class="cm"># ============================================</span>
<span class="cm"># دفتر جهات الاتصال</span>
<span class="cm"># ============================================</span>
<span class="kw">contacts</span> = []

<span class="kw">while</span> <span class="kw">True</span>:
    <span class="fn">print</span>(<span class="st">"\\n1) Add contact  2) Search  3) List all  4) Exit"</span>)
    <span class="kw">choice</span> = <span class="fn">input</span>(<span class="st">"Choose an option: "</span>).strip()

    <span class="kw">if</span> choice == <span class="st">"1"</span>:
        <span class="kw">name</span> = <span class="fn">input</span>(<span class="st">"Name: "</span>).strip()
        <span class="kw">phone</span> = <span class="fn">input</span>(<span class="st">"Phone: "</span>).strip()
        contacts.append({<span class="st">"name"</span>: name, <span class="st">"phone"</span>: phone})
        <span class="fn">print</span>(<span class="st">f"Added {name}"</span>)

    <span class="kw">elif</span> choice == <span class="st">"2"</span>:
        <span class="kw">query</span> = <span class="fn">input</span>(<span class="st">"Search name: "</span>).strip().lower()
        <span class="kw">found</span> = <span class="kw">False</span>
        <span class="kw">for</span> contact <span class="kw">in</span> contacts:
            <span class="kw">if</span> contact[<span class="st">"name"</span>].lower() == query:
                <span class="fn">print</span>(<span class="st">f"{contact['name']}: {contact['phone']}"</span>)
                <span class="kw">found</span> = <span class="kw">True</span>
                <span class="kw">break</span>
        <span class="kw">if</span> <span class="kw">not</span> found:
            <span class="fn">print</span>(<span class="st">"Not found"</span>)

    <span class="kw">elif</span> choice == <span class="st">"3"</span>:
        <span class="kw">if</span> <span class="kw">not</span> contacts:
            <span class="fn">print</span>(<span class="st">"No contacts yet"</span>)
        <span class="kw">for</span> contact <span class="kw">in</span> contacts:
            <span class="fn">print</span>(<span class="st">f"{contact['name']}: {contact['phone']}"</span>)

    <span class="kw">elif</span> choice == <span class="st">"4"</span>:
        <span class="fn">print</span>(<span class="st">"Goodbye!"</span>)
        <span class="kw">break</span>

    <span class="kw">else</span>:
        <span class="fn">print</span>(<span class="st">"Invalid option, try again"</span>)`,
    quiz: {
        q: {
            ar: "لماذا استخدمنا قائمة من القواميس (list of dicts) بدل قاموس واحد كبير لتخزين جهات الاتصال؟",
            en: "Why did we use a list of dicts instead of one big dict to store contacts?"
        },
        options: {
            ar: [
                "لأن القاموس الواحد أبطأ في التنفيذ",
                "لأن قائمة القواميس أكثر مرونة ولا تفترض أن الاسم فريد",
                "لأن القاموس لا يدعم النصوص كقيم",
                "لا فرق فعلي، كلاهما يعمل بنفس الطريقة تماماً"
            ],
            en: [
                "Because a single dict is slower to run",
                "Because a list of dicts is more flexible and doesn't assume names are unique",
                "Because dicts don't support strings as values",
                "There's no real difference, both work identically"
            ]
        },
        correct: 1,
        explanation: {
            ar: "قاموس واحد {اسم: هاتف} يفترض أن كل اسم فريد ويصعب توسيعه ببيانات إضافية لكل جهة اتصال. قائمة القواميس تسمح بأسماء متكررة وحقول إضافية بسهولة — نمط أكثر واقعية ومرونة.",
            en: "A single {name: phone} dict assumes every name is unique and is hard to extend with extra fields per contact. A list of dicts allows duplicate names and extra fields easily — a more realistic, flexible pattern."
        }
    }
}
,

/* ---------- الدرس 22 ---------- */
{
    title: { ar: "الدوال: التعريف والاستدعاء", en: "Functions: defining and calling" },
    body: {
        ar: `
<p>لاحظ في مشروع دفتر جهات الاتصال أنك كتبت <code>print(f"{contact['name']}: {contact['phone']}")</code> في أكثر من مكان. ماذا لو أردت تغيير صيغة العرض لاحقاً؟ ستُضطر لتعديلها في كل موضع، وستنسى مكاناً حتماً. <strong>الدالة (function)</strong> تحلّ هذه المشكلة: تكتب منطقاً معيّناً <strong>مرة واحدة</strong> باسم، ثم تستدعيه بذلك الاسم من أي مكان في برنامجك.</p>

<h3>تعريف دالة واستدعاؤها</h3>

<p>تُعرَّف الدالة بالكلمة المفتاحية <code>def</code> متبوعة باسم واصف، ثم قوسين، ثم نقطتين، ثم جسم الدالة بمسافة بادئة: <code>def greet(): print("Hello")</code>. تعريف الدالة وحده <strong>لا ينفّذ شيئاً</strong> — يجب <strong>استدعاؤها</strong> باسمها متبوعاً بقوسين: <code>greet()</code>. هذا فرق مهم يُخطئ فيه المبتدئون كثيراً: نسيان القوسين عند الاستدعاء لا يستدعي الدالة، بل يشير إليها فقط ككائن.</p>

<h3>لماذا نكتب دوال؟</h3>

<p>ثلاثة أسباب: <strong>تجنّب التكرار</strong> (اكتب مرة، استخدم مرات لا نهائية)، <strong>التنظيم</strong> (كل دالة تفعل شيئاً واحداً واضحاً، فيصبح البرنامج الكبير مجموعة أجزاء مفهومة)، و<strong>إعادة الاستخدام</strong> (يمكن استدعاء نفس الدالة من مشاريع مختلفة).</p>

<h3>التوثيق بـ Docstring</h3>

<p>من الممارسات الجيدة إضافة سطر توثيقي داخل الدالة مباشرة بعد تعريفها، بين ثلاث علامات تنصيص: <code>"""يشرح ما تفعله الدالة"""</code>. هذا يساعد أي شخص (بما فيك أنت بعد شهر) على فهم الغرض دون قراءة الكود كاملاً.</p>

<h3>أخطاء شائعة</h3>

<p><strong>نسيان القوسين عند الاستدعاء:</strong> <code>greet</code> بدون أقواس لا يُنفّذ الدالة، بل يطبع مرجعاً إليها مثل <code>&lt;function greet at 0x...&gt;</code>. <strong>استدعاء دالة قبل تعريفها:</strong> بايثون تقرأ الملف من الأعلى للأسفل، فيجب أن يظهر تعريف <code>def</code> قبل أي استدعاء لها في الكود.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>الدالة كتلة كود معاد استخدامها، تُعرَّف بـ <code>def name():</code></li>
    <li>تعريف الدالة لا ينفّذها — يجب استدعاؤها بالاسم والقوسين: <code>name()</code></li>
    <li>الدوال تمنع التكرار وتنظّم البرنامج إلى أجزاء واضحة</li>
    <li>Docstring يوثّق غرض الدالة داخل جسمها مباشرة</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>اكتب دالة <code>print_separator()</code> تطبع 30 شرطة، وأخرى <code>print_welcome()</code> تطبع رسالة ترحيب. استدعِ الاثنتين بترتيب يُنتج: فاصلاً، ثم الترحيب، ثم فاصلاً مرة أخرى.</p>
`,
        en: `<p>A function packages reusable logic under a name using def name():. Defining a function does not run it — you must call it with name(). Functions avoid repetition, organize code into clear pieces, and can be reused anywhere in the program.</p>`
    },
    code: `<span class="cm"># تعريف دالة بسيطة بلا معاملات</span>
<span class="kw">def</span> greet():
    <span class="st">"""Prints a simple welcome message"""</span>
    <span class="fn">print</span>(<span class="st">"Hello!"</span>)

<span class="cm"># تعريف الدالة وحده لا ينفّذ شيئاً — يجب استدعاؤها</span>
greet()
greet()      <span class="cm"># يمكن استدعاؤها عدة مرات</span>


<span class="cm"># خطأ شائع: نسيان الأقواس عند الاستدعاء</span>
<span class="fn">print</span>(greet)     <span class="cm"># &lt;function greet at 0x...&gt; — لم يُنفَّذ!</span>
<span class="fn">print</span>(greet())   <span class="cm"># ينفّذها ثم يطبع الناتج (None هنا)</span>


<span class="cm"># مثال عملي: دالتان تتعاونان</span>
<span class="kw">def</span> print_separator():
    <span class="fn">print</span>(<span class="st">"-"</span> * 30)

<span class="kw">def</span> print_welcome():
    <span class="fn">print</span>(<span class="st">"Welcome to Koudna!"</span>)

print_separator()
print_welcome()
print_separator()`,
    quiz: {
        q: {
            ar: "ماذا يحدث عند كتابة greet بدون أقواس بعد تعريفها؟",
            en: "What happens when you write greet without parentheses after defining it?"
        },
        options: {
            ar: [
                "تُنفَّذ الدالة فوراً كأي استدعاء عادي",
                "لا شيء يُنفَّذ — تشير فقط إلى الدالة كقيمة، دون استدعائها",
                "يرمي بايثون خطأً فورياً",
                "تُنفَّذ الدالة لكن دون طباعة أي شيء"
            ],
            en: [
                "The function executes immediately, like a normal call",
                "Nothing executes — it just references the function as a value, without calling it",
                "Python raises an immediate error",
                "The function executes but prints nothing"
            ]
        },
        correct: 1,
        explanation: {
            ar: "الأقواس () هي ما يُنفّذ الدالة فعلياً. بدونها، الاسم greet يشير فقط إلى الدالة نفسها ككائن، دون تشغيل أي كود بداخلها — وهذا فخّ شائع جداً للمبتدئين.",
            en: "The parentheses () are what actually execute the function. Without them, the name greet just refers to the function object itself, without running any code inside it — a very common beginner trap."
        }
    }
},

/* ---------- الدرس 23 ---------- */
{
    title: { ar: "المعاملات: تمرير القيم للدوال", en: "Parameters: passing values to functions" },
    body: {
        ar: `
<p>الدالة <code>greet()</code> من الدرس السابق تطبع نفس الرسالة دائماً — محدودة الفائدة. ماذا لو أردت تحية اسم مختلف كل مرة؟ هنا تحتاج <strong>المعاملات (parameters)</strong>: قيم تُمرَّر للدالة عند استدعائها، فتتصرّف الدالة بناءً عليها بدل أن تكون ثابتة الفعل دائماً.</p>

<h3>معامل واحد ومعاملات متعددة</h3>

<p>يُكتب المعامل داخل قوسي تعريف الدالة: <code>def greet(name): print(f"Hello, {name}")</code>. عند الاستدعاء، تمرّر <strong>وسيطاً (argument)</strong> فعلياً: <code>greet("Sarah")</code>. يمكن لدالة أن تأخذ عدة معاملات مفصولة بفواصل: <code>def add(a, b): return a + b</code>.</p>

<h3>القيم الافتراضية (Default Values)</h3>

<p>يمكن إعطاء معامل قيمة افتراضية تُستخدم إن لم يُمرَّر وسيط له: <code>def greet(name="friend"):</code>. استدعاء <code>greet()</code> بلا وسيط يستخدم "friend"، بينما <code>greet("Sarah")</code> يتجاوز الافتراضي بالقيمة الممرَّرة. القاعدة الصارمة: المعاملات ذات القيم الافتراضية يجب أن تأتي <strong>بعد</strong> المعاملات العادية في التعريف.</p>

<h3>الوسائط الموضعية والمسمّاة</h3>

<p>الاستدعاء الموضعي (positional) يعتمد على الترتيب: <code>add(3, 5)</code> يُسند 3 لـ a و5 لـ b تلقائياً. الاستدعاء المسمّى (keyword) يحدّد الاسم صراحة: <code>add(b=5, a=3)</code> — يعمل بغض النظر عن الترتيب، ويجعل الكود أوضح خصوصاً مع دوال كثيرة المعاملات.</p>

<h3>أخطاء شائعة</h3>

<p>نسيان تمرير معامل مطلوب يرمي <code>TypeError: missing required positional argument</code>. وكذلك الخلط في الترتيب عند الاستدعاء الموضعي — <code>greet_full("أحمد", "محمد")</code> قد تعكس الاسم واللقب إن لم تتذكّر ترتيب التعريف الدقيق؛ استخدم الوسائط المسمّاة عندما يكون الترتيب غير واضح.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>المعاملات تجعل الدالة تتصرّف بحسب القيم المُمرَّرة إليها</li>
    <li>القيم الافتراضية <code>def f(x=default):</code> تُستخدم عند عدم تمرير وسيط</li>
    <li>الاستدعاء الموضعي يعتمد الترتيب، والمسمّى يحدّد الاسم صراحة</li>
    <li>معاملات القيم الافتراضية تأتي دائماً بعد المعاملات العادية في التعريف</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>اكتب دالة <code>describe_pet(name, animal="dog")</code> تطبع جملة تصف الحيوان الأليف. استدعِها ثلاث مرات: بمعاملين، بمعامل واحد فقط (استخدام الافتراضي)، وبوسائط مسمّاة بترتيب معكوس.</p>
`,
        en: `<p>Parameters let a function behave differently based on values passed in: def f(param). Default values (def f(x=default)) apply when no argument is given. Positional calls rely on order; keyword calls (f(x=1)) name the parameter explicitly, which is clearer with many parameters.</p>`
    },
    code: `<span class="cm"># معامل واحد</span>
<span class="kw">def</span> greet(name):
    <span class="fn">print</span>(<span class="st">f"Hello, {name}"</span>)

greet(<span class="st">"Sarah"</span>)
greet(<span class="st">"Ahmed"</span>)


<span class="cm"># معاملات متعددة</span>
<span class="kw">def</span> add(a, b):
    <span class="fn">print</span>(<span class="st">f"{a} + {b} = {a + b}"</span>)

add(3, 5)


<span class="cm"># قيمة افتراضية</span>
<span class="kw">def</span> greet_default(name=<span class="st">"friend"</span>):
    <span class="fn">print</span>(<span class="st">f"Hello, {name}"</span>)

greet_default()          <span class="cm"># Hello, friend</span>
greet_default(<span class="st">"Layla"</span>)  <span class="cm"># Hello, Layla — يتجاوز الافتراضي</span>


<span class="cm"># استدعاء موضعي مقابل مسمّى</span>
<span class="kw">def</span> describe_pet(name, animal=<span class="st">"dog"</span>):
    <span class="fn">print</span>(<span class="st">f"{name} is a {animal}"</span>)

describe_pet(<span class="st">"Rex"</span>, <span class="st">"cat"</span>)             <span class="cm"># موضعي</span>
describe_pet(animal=<span class="st">"parrot"</span>, name=<span class="st">"Coco"</span>)  <span class="cm"># مسمّى — الترتيب لا يهم</span>


<span class="cm"># خطأ شائع: نسيان معامل مطلوب</span>
<span class="cm"># greet()   ← TypeError: missing 1 required positional argument</span>`,
    quiz: {
        q: {
            ar: "def greet(name=\"friend\"): print(name)\nما ناتج استدعاء greet(\"Sarah\")؟",
            en: "def greet(name=\"friend\"): print(name)\nWhat does greet(\"Sarah\") print?"
        },
        options: { ar: ["friend", "Sarah", "خطأ لأن الدالة تأخذ معاملاً واحداً فقط", "لا شيء"], en: ["friend", "Sarah", "An error because the function only takes one parameter", "Nothing"] },
        correct: 1,
        explanation: {
            ar: "تمرير 'Sarah' كوسيط موضعي يتجاوز القيمة الافتراضية 'friend' تماماً، فتصبح name تساوي 'Sarah' داخل الدالة. القيمة الافتراضية تُستخدم فقط عند عدم تمرير أي وسيط.",
            en: "Passing 'Sarah' as a positional argument overrides the default value 'friend' entirely, so name becomes 'Sarah' inside the function. The default is only used when no argument is passed at all."
        }
    }
},

/* ---------- الدرس 24 ---------- */
{
    title: { ar: "return: إرجاع قيمة من الدالة", en: "return: getting a value back from a function" },
    body: {
        ar: `
<p>الدوال في الدروس السابقة كانت <strong>تطبع</strong> نتائجها مباشرة بـ <code>print()</code>. لكن ماذا لو أردت استخدام نتيجة الدالة لاحقاً في حساب آخر، أو تخزينها في متغيّر؟ الطباعة لا تكفي — تحتاج الدالة أن <strong>تُرجع</strong> قيمة فعلية يمكن التقاطها واستخدامها. هنا يأتي دور <code>return</code>.</p>

<h3>الفرق الجوهري بين print وreturn</h3>

<p><code>print()</code> تعرض نصاً على الشاشة للمستخدم فقط — لا يمكن للبرنامج "استخدام" ما طُبع برمجياً. <code>return</code> تُخرج قيمة فعلية من الدالة يمكن تخزينها في متغيّر، تمريرها لدالة أخرى، أو استخدامها في عملية حسابية: <code>result = add(3, 5)</code> يخزّن الناتج الفعلي في <code>result</code>، بينما دالة تكتفي بـ <code>print</code> تجعل <code>result</code> يساوي <code>None</code>.</p>

<h3>return تُنهي الدالة فوراً</h3>

<p>بمجرّد تنفيذ <code>return</code>، تتوقّف الدالة فوراً — أي كود بعدها في نفس المسار لن يُنفَّذ أبداً. هذا يُستخدم أحياناً عمداً للخروج المبكّر من دالة عند تحقّق شرط معيّن، تماماً مثل <code>break</code> في الحلقات.</p>

<h3>إرجاع عدة قيم دفعة واحدة</h3>

<p>بايثون تسمح بإرجاع أكثر من قيمة مفصولة بفواصل: <code>return name, age</code> — وهذا فعلياً يُرجع Tuple واحداً يمكن تفكيكه مباشرة عند الاستدعاء: <code>n, a = get_info()</code>، بنفس منطق تفكيك Tuple الذي تعلمته سابقاً.</p>

<h3>أخطاء شائعة</h3>

<p><strong>نسيان return والاعتماد على print فقط:</strong> إن احتجت النتيجة لاستخدامها لاحقاً وليس فقط لعرضها، فـ<code>print</code> وحده غير كافٍ. <strong>الخلط بين الاثنين:</strong> استخدام <code>print()</code> ثم توقّع أن الدالة "تُرجع" شيئاً — دالة بلا <code>return</code> صريح تُرجع <code>None</code> تلقائياً دائماً.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li><code>return</code> يُخرج قيمة فعلية يمكن استخدامها برمجياً، بخلاف <code>print</code> الذي يعرض فقط</li>
    <li>الدالة بلا <code>return</code> صريح تُرجع <code>None</code> تلقائياً</li>
    <li><code>return</code> يُنهي تنفيذ الدالة فوراً — أي كود بعده لا يُنفَّذ</li>
    <li>يمكن إرجاع عدة قيم كـ Tuple: <code>return a, b</code></li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>اكتب دالة <code>calculate_rectangle(width, height)</code> تُرجع المساحة والمحيط معاً (قيمتين). استدعِها وخزّن الناتجين في متغيّرين منفصلين، ثم اطبعهما بجملة واضحة.</p>
`,
        en: `<p>print() only displays text; return actually hands a value back to the caller so it can be stored or reused: result = add(3, 5). return also ends the function immediately. A function with no explicit return always returns None, and multiple values can be returned as a tuple: return a, b.</p>`
    },
    code: `<span class="cm"># print فقط يعرض، لا يُرجع شيئاً قابلاً للاستخدام</span>
<span class="kw">def</span> add_print(a, b):
    <span class="fn">print</span>(a + b)

<span class="kw">result1</span> = add_print(3, 5)   <span class="cm"># يطبع 8</span>
<span class="fn">print</span>(result1)                <span class="cm"># None — لا قيمة فعلية!</span>


<span class="cm"># return يُخرج قيمة فعلية قابلة للاستخدام</span>
<span class="kw">def</span> add_return(a, b):
    <span class="kw">return</span> a + b

<span class="kw">result2</span> = add_return(3, 5)
<span class="fn">print</span>(result2)                <span class="cm"># 8 — قيمة حقيقية</span>
<span class="fn">print</span>(result2 * 2)            <span class="cm"># 16 — يمكن استخدامها في عملية أخرى</span>


<span class="cm"># return تُنهي الدالة فوراً</span>
<span class="kw">def</span> check_age(age):
    <span class="kw">if</span> age < 0:
        <span class="kw">return</span> <span class="st">"Invalid age"</span>   <span class="cm"># يخرج هنا فوراً</span>
    <span class="kw">return</span> <span class="st">f"Age is {age}"</span>       <span class="cm"># لن يصل هنا إلا إن كان العمر صالحاً</span>

<span class="fn">print</span>(check_age(-5))
<span class="fn">print</span>(check_age(25))


<span class="cm"># إرجاع عدة قيم دفعة واحدة</span>
<span class="kw">def</span> calculate_rectangle(width, height):
    <span class="kw">area</span> = width * height
    <span class="kw">perimeter</span> = 2 * (width + height)
    <span class="kw">return</span> area, perimeter

<span class="kw">a</span>, <span class="kw">p</span> = calculate_rectangle(4, 6)
<span class="fn">print</span>(<span class="st">f"Area: {a}, Perimeter: {p}"</span>)`,
    quiz: {
        q: {
            ar: "def get_value():\n    print(\"hi\")\nx = get_value()\nما قيمة x؟",
            en: "def get_value():\n    print(\"hi\")\nx = get_value()\nWhat is the value of x?"
        },
        options: { ar: ["\"hi\"", "None", "0", "خطأ في التنفيذ"], en: ["\"hi\"", "None", "0", "A runtime error"] },
        correct: 1,
        explanation: {
            ar: "الدالة تطبع 'hi' لكنها لا تحتوي أي جملة return صريحة. أي دالة بلا return صريح تُرجع None تلقائياً في بايثون، بغض النظر عمّا طبعته على الشاشة.",
            en: "The function prints 'hi' but has no explicit return statement. Any function without an explicit return automatically returns None in Python, regardless of what it printed to the screen."
        }
    }
},

/* ---------- الدرس 25 ---------- */
{
    title: { ar: "نطاق المتغيّرات (Scope)", en: "Variable scope" },
    body: {
        ar: `
<p>جرّب هذا: عرّف متغيّراً داخل دالة، ثم حاول استخدامه خارجها بعد استدعائها — ستحصل على <code>NameError</code>! هذا ليس خطأً، بل قاعدة أساسية في بايثون تُسمّى <strong>النطاق (Scope)</strong>: أين يمكن "رؤية" متغيّر معيّن واستخدامه في البرنامج.</p>

<h3>النطاق المحلي مقابل العام</h3>

<p>أي متغيّر يُعرَّف <strong>داخل</strong> دالة هو <strong>محلي (local)</strong> — يوجد فقط أثناء تنفيذ تلك الدالة، ويُمحى تماماً بعد انتهائها. المتغيّرات المعرَّفة <strong>خارج</strong> كل الدوال، على مستوى الملف الرئيسي، تُسمّى <strong>عامّة (global)</strong> — يمكن قراءتها من داخل أي دالة.</p>

<h3>القراءة من الخارج مسموحة، الكتابة ممنوعة افتراضياً</h3>

<p>يمكن لأي دالة أن <strong>تقرأ</strong> متغيّراً عامّاً دون مشكلة. لكن محاولة <strong>تعديل</strong> متغيّر عامّ من داخل دالة بإسناد قيمة جديدة له، ستُنشئ متغيّراً محلياً جديداً بنفس الاسم بدلاً من تعديل الأصلي — فخّ خفي جداً للمبتدئين، لأن الكود لا يرمي خطأً، بل يتصرّف بشكل غير متوقّع بصمت.</p>

<h3>الكلمة المفتاحية global</h3>

<p>إن احتجت فعلاً تعديل متغيّر عامّ من داخل دالة (نادراً ما يكون هذا التصميم الأفضل)، يجب التصريح صراحة بـ <code>global variable_name</code> في أول سطر داخل الدالة قبل التعديل. لكن الممارسة الأفضل غالباً: مرّر القيمة كمعامل، واستخدم <code>return</code> لإخراج النتيجة، بدل الاعتماد على متغيّرات عامّة معدَّلة من كل مكان.</p>

<h3>أخطاء شائعة</h3>

<p>افتراض أن متغيّراً محلياً داخل دالة سيبقى متاحاً بعد انتهائها — لن يبقى. ومحاولة تعديل متغيّر عامّ داخل دالة دون <code>global</code>، فتحصل على سلوك مربك: القيمة العامة لا تتغيّر، بل يُنشأ متغيّر محلي منفصل تماماً بنفس الاسم.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>المتغيّر داخل دالة هو <strong>محلي</strong>: يوجد فقط أثناء تنفيذها، ثم يُمحى</li>
    <li>المتغيّر خارج كل الدوال هو <strong>عامّ</strong>: يمكن قراءته من أي دالة</li>
    <li>تعديل متغيّر عامّ من داخل دالة يحتاج تصريح <code>global</code> صريح</li>
    <li>الأفضل تصميمياً: مرّر القيم كمعاملات، وأرجع النتائج بـ <code>return</code></li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>عرّف متغيّراً عامّاً <code>total_score = 0</code>. اكتب دالة <code>add_points(points)</code> تحاول تعديله مباشرة بدون <code>global</code> ولاحظ أن القيمة العامة لا تتغيّر، ثم أعد كتابتها باستخدام <code>global</code> صراحة وشاهد الفرق.</p>
`,
        en: `<p>Variables defined inside a function are local — they exist only during that call and disappear afterward. Variables defined outside any function are global and readable everywhere, but modifying a global from inside a function needs an explicit global keyword, otherwise Python silently creates a separate local variable instead.</p>`
    },
    code: `<span class="cm"># متغيّر محلي — يوجد فقط داخل الدالة</span>
<span class="kw">def</span> greet():
    <span class="kw">message</span> = <span class="st">"Hello!"</span>   <span class="cm"># محلي</span>
    <span class="fn">print</span>(message)

greet()
<span class="cm"># print(message)   ← NameError: message غير معروف هنا!</span>


<span class="cm"># متغيّر عامّ — يمكن قراءته من أي دالة</span>
<span class="kw">site_name</span> = <span class="st">"Koudna"</span>

<span class="kw">def</span> show_name():
    <span class="fn">print</span>(site_name)   <span class="cm"># قراءة فقط — تعمل بلا مشاكل</span>

show_name()


<span class="cm"># فخّ شائع: التعديل بدون global لا يؤثر على المتغيّر العام</span>
<span class="kw">total</span> = 0

<span class="kw">def</span> add_wrong(points):
    <span class="kw">total</span> = total + points   <span class="cm"># هذا يُنشئ متغيّراً محلياً منفصلاً!</span>

add_wrong(10)
<span class="fn">print</span>(total)   <span class="cm"># لا يزال 0 — لم يتغيّر</span>


<span class="cm"># الحل الصحيح: التصريح بـ global</span>
<span class="kw">def</span> add_correct(points):
    <span class="kw">global</span> total
    total = total + points

add_correct(10)
<span class="fn">print</span>(total)   <span class="cm"># 10 — تغيّر فعلاً</span>`,
    quiz: {
        q: {
            ar: "score = 0\ndef change():\n    score = 100\nchange()\nprint(score)\nما الناتج؟",
            en: "score = 0\ndef change():\n    score = 100\nchange()\nprint(score)\nWhat is printed?"
        },
        options: { ar: ["100", "0", "خطأ NameError", "None"], en: ["100", "0", "A NameError", "None"] },
        correct: 1,
        explanation: {
            ar: "بدون التصريح بـ global داخل change()، السطر score = 100 يُنشئ متغيّراً محلياً منفصلاً تماماً عن المتغيّر العام score. المتغيّر العام يبقى 0 دون أي تغيير.",
            en: "Without declaring global inside change(), the line score = 100 creates a completely separate local variable from the global score. The global variable stays 0, unchanged."
        }
    }
},

/* ---------- الدرس 26 ---------- */
{
    title: { ar: "lambda والدوال كقيم", en: "lambda and functions as values" },
    body: {
        ar: `
<p>حتى الآن، تعاملت مع الدوال ككتل كود بأسماء تستدعيها. لكن في بايثون، الدالة هي أيضاً <strong>قيمة</strong> ككل شيء آخر — يمكن تخزينها في متغيّر، تمريرها لدالة أخرى كمعامل، أو حتى إرجاعها من دالة. هذه المرونة تفتح الباب لأداة صغيرة لكنها شائعة جداً: <strong>lambda</strong>، دالة مختصرة بلا اسم تُكتب بسطر واحد.</p>

<h3>صيغة lambda</h3>

<p>الصيغة: <code>lambda parameters: expression</code>. مثال: <code>square = lambda x: x**2</code> يُنشئ دالة تحسب المربّع، تُستدعى بنفس طريقة أي دالة عادية: <code>square(5)</code> يعطي 25. لاحظ الفرق عن <code>def</code>: لا حاجة لـ <code>return</code> صراحة — القيمة الناتجة عن التعبير تُرجع تلقائياً، لكن لا يمكن أن يحتوي جسمها أكثر من تعبير واحد.</p>

<h3>لماذا نستخدم lambda عملياً؟</h3>

<p>الاستخدام الأشيع: كمعامل مؤقت لدالة أخرى تحتاج دالة صغيرة، دون داعٍ لتعريف دالة كاملة بـ <code>def</code> باسم منفصل. المثال الكلاسيكي: <code>sorted(students, key=lambda s: s["grade"])</code> يرتّب قائمة قواميس حسب مفتاح "grade" — بدون lambda، ستحتاج تعريف دالة منفصلة فقط لهذا الترتيب الواحد.</p>

<h3>الدوال كمعاملات (Higher-Order Functions)</h3>

<p>القدرة على تمرير دالة (بما فيها lambda) كمعامل لدالة أخرى تُسمّى Higher-Order Function. <code>sorted()</code> مثال مباشر: معامل <code>key</code> يقبل أي دالة تُحدّد "بماذا نرتّب". هذا نمط قوي جداً ستراه كثيراً في بايثون الاحترافية.</p>

<h3>متى نتجنّب lambda؟</h3>

<p>إن كان المنطق أكثر تعقيداً من تعبير واحد بسيط، استخدم <code>def</code> عادية بدلاً من lambda — القراءة أهم من الاختصار. القاعدة العملية: lambda مثالية لعمليات بسيطة سطر واحد (مفتاح ترتيب، شرط تصفية بسيط)، وليست بديلاً عاماً عن الدوال العادية.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>lambda دالة مختصرة بلا اسم بسطر واحد: <code>lambda params: expr</code></li>
    <li>القيمة الناتجة عن التعبير تُرجع تلقائياً — بلا <code>return</code> صريح</li>
    <li>تُستخدم غالباً كمعامل مؤقت لدوال أخرى، مثل <code>key</code> في <code>sorted()</code></li>
    <li>استخدم <code>def</code> عادية للمنطق الأكثر تعقيداً من تعبير واحد</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>لديك قائمة قواميس لطلاب فيها "name" و"grade". استخدم <code>sorted()</code> مع <code>key=lambda</code> لترتيبهم حسب الدرجة تنازلياً، ثم اطبع أسماءهم بالترتيب الجديد.</p>
`,
        en: `<p>lambda creates a small unnamed function in one line: lambda params: expression, with the expression's value returned automatically. It's most useful as a temporary function argument, like sorted(data, key=lambda x: x["field"]) — a pattern called a higher-order function.</p>`
    },
    code: `<span class="cm"># دالة عادية مقابل lambda مكافئة</span>
<span class="kw">def</span> square_def(x):
    <span class="kw">return</span> x**2

<span class="kw">square_lambda</span> = <span class="kw">lambda</span> x: x**2

<span class="fn">print</span>(square_def(5))       <span class="cm"># 25</span>
<span class="fn">print</span>(square_lambda(5))    <span class="cm"># 25 — نفس النتيجة</span>


<span class="cm"># lambda بعدة معاملات</span>
<span class="kw">add</span> = <span class="kw">lambda</span> a, b: a + b
<span class="fn">print</span>(add(3, 5))          <span class="cm"># 8</span>


<span class="cm"># الاستخدام الأشيع: كمعامل key في sorted()</span>
<span class="kw">students</span> = [
    {<span class="st">"name"</span>: <span class="st">"Sarah"</span>, <span class="st">"grade"</span>: 85},
    {<span class="st">"name"</span>: <span class="st">"Ahmed"</span>, <span class="st">"grade"</span>: 95},
    {<span class="st">"name"</span>: <span class="st">"Layla"</span>, <span class="st">"grade"</span>: 78}
]

<span class="kw">by_grade</span> = <span class="fn">sorted</span>(students, key=<span class="kw">lambda</span> s: s[<span class="st">"grade"</span>], reverse=<span class="kw">True</span>)
<span class="kw">for</span> student <span class="kw">in</span> by_grade:
    <span class="fn">print</span>(<span class="st">f"{student['name']}: {student['grade']}"</span>)


<span class="cm"># مثال آخر: فلترة بـ filter و lambda</span>
<span class="kw">numbers</span> = [1, 2, 3, 4, 5, 6, 7, 8]
<span class="kw">evens</span> = <span class="fn">list</span>(<span class="fn">filter</span>(<span class="kw">lambda</span> n: n % 2 == 0, numbers))
<span class="fn">print</span>(evens)   <span class="cm"># [2, 4, 6, 8]</span>`,
    quiz: {
        q: {
            ar: "أي كود يرتّب قائمة أسماء products حسب سعرها (مفتاح price) تصاعدياً؟",
            en: "Which code sorts a list of products by their price key, ascending?"
        },
        options: {
            ar: [
                "sorted(products, key=lambda p: p[\"price\"])",
                "sorted(products, lambda p: p[\"price\"])",
                "products.sort(\"price\")",
                "sorted(products, price)"
            ],
            en: [
                "sorted(products, key=lambda p: p[\"price\"])",
                "sorted(products, lambda p: p[\"price\"])",
                "products.sort(\"price\")",
                "sorted(products, price)"
            ]
        },
        correct: 0,
        explanation: {
            ar: "المعامل key يجب تحديده صراحة باسمه، ويُعطى دالة (هنا lambda) تُحدّد أي جزء من كل عنصر يُستخدم للمقارنة أثناء الترتيب. الترتيب التصاعدي هو الافتراضي بلا حاجة لأي معامل إضافي.",
            en: "The key parameter must be named explicitly and given a function (here a lambda) that determines what part of each item to compare during sorting. Ascending order is the default, needing no extra parameter."
        }
    }
},

/* ---------- الدرس 27 — مشروع ---------- */
{
    title: { ar: "مشروع 4: أدوات نصية", en: "Project 4: Text tools" },
    body: {
        ar: `
<p>مشروع هذا المستوى يجمع كل ما تعلمته عن الدوال: التعريف والاستدعاء، المعاملات والقيم الافتراضية، <code>return</code>، النطاق، وlambda. ستبني مجموعة أدوات نصية (Text Tools) — كل أداة دالة منفصلة، يستدعيها البرنامج الرئيسي حسب اختيار المستخدم.</p>

<h3>لماذا نقسّم المشروع إلى دوال؟</h3>

<p>بدل كتابة كل منطق البرنامج في حلقة <code>while</code> واحدة ضخمة (كما فعلت في مشروع دفتر جهات الاتصال)، هذه المرة كل عملية نصية (عدّ الكلمات، عكس النص، تحويل الأحرف) هي دالة منفصلة بمعامل واحد ونتيجة مُرجَعة. هذا يجعل كل جزء قابلاً للاختبار بمفرده، وقابلاً لإعادة الاستخدام في مشاريع أخرى لاحقاً.</p>

<h3>تصميم كل أداة كدالة نقية</h3>

<p>لاحظ أن كل دالة في هذا المشروع <strong>تستقبل نصاً وتُرجع نتيجة</strong>، دون طباعة داخلها مباشرة (Pure Function). الطباعة تحدث فقط في الحلقة الرئيسية بعد استدعاء الدالة. هذا الفصل بين "الحساب" و"العرض" ممارسة احترافية مهمة: تسهّل اختبار الدوال منفصلة عن واجهة المستخدم.</p>

<h3>استخدام lambda للاختصار</h3>

<p>بعض الأدوات البسيطة جداً (مثل تحويل لأحرف كبيرة) يمكن كتابتها بـ lambda مباشرة بدل <code>def</code> كاملة، بينما الأدوات الأعقد (عدّ الكلمات، عكس الجمل) تحتاج <code>def</code> عادية بجسم متعدد الأسطر.</p>

<h3>تحديات للتوسيع</h3>

<ul>
    <li>أضف أداة لعدّ الأحرف بدون المسافات</li>
    <li>أضف أداة تتحقّق إن كان النصّ متناظراً (palindrome) — يُقرأ نفسه من الجهتين</li>
    <li>اجعل القائمة الرئيسية تُبنى ديناميكياً من قاموس يربط الاختيار بالدالة المناسبة، بدل سلسلة طويلة من <code>if/elif</code></li>
</ul>

<h3>ماذا أنجزت في هذا المستوى؟</h3>

<ul>
    <li>نظّمت الكود بدوال بدل تكرار نفس المنطق في أماكن متعددة</li>
    <li>تحكّمت بسلوك الدوال عبر المعاملات والقيم الافتراضية</li>
    <li>ميّزت بوضوح بين <code>print</code> (عرض) وbين <code>return</code> (إرجاع قيمة فعلية للاستخدام)</li>
    <li>فهمت نطاق المتغيّرات المحلي والعام وتجنّبت فخّ التعديل الصامت</li>
    <li>استخدمت lambda للدوال الصغيرة السريعة، خصوصاً كمعامل <code>key</code></li>
    <li>وبنيت مجموعة أدوات نصية حقيقية مبنية على دوال نقية قابلة لإعادة الاستخدام</li>
</ul>

<p>في المستوى الخامس سنتعلّم كيف يتعامل برنامجك مع الملفات الحقيقية على القرص، وكيف يتعافى بأناقة من الأخطاء غير المتوقّعة بدل التوقّف المفاجئ.</p>
`,
        en: `<p>This project builds a text-tools menu where each operation (word count, reverse, case conversion) is its own pure function — takes text, returns a result, with printing kept only in the main loop. It combines def, parameters, return, scope, and lambda from this level into one program.</p>`
    },
    code: `<span class="cm"># ============================================</span>
<span class="cm"># أدوات نصية</span>
<span class="cm"># ============================================</span>

<span class="kw">def</span> count_words(text):
    <span class="kw">return</span> <span class="fn">len</span>(text.split())

<span class="kw">def</span> reverse_text(text):
    <span class="kw">return</span> text[::-1]

<span class="kw">def</span> count_vowels(text):
    <span class="kw">vowels</span> = <span class="st">"aeiouAEIOU"</span>
    <span class="kw">count</span> = 0
    <span class="kw">for</span> ch <span class="kw">in</span> text:
        <span class="kw">if</span> ch <span class="kw">in</span> vowels:
            count += 1
    <span class="kw">return</span> count

<span class="cm"># أداة بسيطة بـ lambda</span>
<span class="kw">to_upper</span> = <span class="kw">lambda</span> text: text.upper()


<span class="kw">while</span> <span class="kw">True</span>:
    <span class="fn">print</span>(<span class="st">"\\n1) Count words  2) Reverse  3) Count vowels  4) Uppercase  5) Exit"</span>)
    <span class="kw">choice</span> = <span class="fn">input</span>(<span class="st">"Choose an option: "</span>).strip()

    <span class="kw">if</span> choice == <span class="st">"5"</span>:
        <span class="fn">print</span>(<span class="st">"Goodbye!"</span>)
        <span class="kw">break</span>

    <span class="kw">text</span> = <span class="fn">input</span>(<span class="st">"Enter text: "</span>)

    <span class="kw">if</span> choice == <span class="st">"1"</span>:
        <span class="fn">print</span>(<span class="st">f"Word count: {count_words(text)}"</span>)
    <span class="kw">elif</span> choice == <span class="st">"2"</span>:
        <span class="fn">print</span>(<span class="st">f"Reversed: {reverse_text(text)}"</span>)
    <span class="kw">elif</span> choice == <span class="st">"3"</span>:
        <span class="fn">print</span>(<span class="st">f"Vowels: {count_vowels(text)}"</span>)
    <span class="kw">elif</span> choice == <span class="st">"4"</span>:
        <span class="fn">print</span>(<span class="st">f"Uppercase: {to_upper(text)}"</span>)
    <span class="kw">else</span>:
        <span class="fn">print</span>(<span class="st">"Invalid option"</span>)`,
    quiz: {
        q: {
            ar: "لماذا صُمِّمت دوال count_words وreverse_text لتُرجع النتيجة بدل طباعتها مباشرة؟",
            en: "Why were count_words and reverse_text designed to return their result instead of printing it directly?"
        },
        options: {
            ar: [
                "لأن print() لا يعمل داخل الدوال",
                "لفصل الحساب عن العرض، فتصبح الدوال قابلة للاختبار وإعادة الاستخدام في سياقات أخرى",
                "لأن return أسرع من print دائماً",
                "لا سبب حقيقي، الاختيار عشوائي"
            ],
            en: [
                "Because print() doesn't work inside functions",
                "To separate computation from display, making functions testable and reusable elsewhere",
                "Because return is always faster than print",
                "No real reason, it was an arbitrary choice"
            ]
        },
        correct: 1,
        explanation: {
            ar: "دالة تُرجع نتيجة (pure function) يمكن استدعاؤها من أي سياق واستخدام ناتجها كما يشاء المستدعي — طباعة، تخزين، أو تمرير لدالة أخرى. دالة تطبع مباشرة مقيّدة بحالة استخدام واحدة فقط.",
            en: "A function that returns a result (a pure function) can be called from any context and its output used however the caller wants — printed, stored, or passed to another function. A function that prints directly is locked into a single use case."
        }
    }
}
,

/* ---------- الدرس 28 ---------- */
{
    title: { ar: "قراءة الملفات وكتابتها", en: "Reading and writing files" },
    body: {
        ar: `
<p>كل برنامج تعلّمته حتى الآن يفقد بياناته بمجرد إغلاقه — قائمة المهام، دفتر جهات الاتصال، كل شيء يختفي عند إعادة التشغيل. البرامج الحقيقية تحتاج تخزين بيانات <strong>دائم</strong> يبقى بعد إغلاق البرنامج، على القرص الصلب مباشرة. هذا الدرس يعلّمك كيف يقرأ برنامجك من ملف حقيقي ويكتب إليه.</p>

<h3>فتح ملف بـ open()</h3>

<p>الدالة <code>open(filename, mode)</code> تفتح ملفاً وتُرجع كائن ملف يمكن القراءة منه أو الكتابة إليه. أهم الأوضاع (modes): <code>"r"</code> للقراءة (الافتراضي)، <code>"w"</code> للكتابة (يمحو المحتوى الموجود بالكامل إن كان الملف موجوداً!)، و<code>"a"</code> للإضافة في نهاية الملف دون محو ما سبق.</p>

<h3>القراءة: read وreadline وreadlines</h3>

<p><code>file.read()</code> تقرأ محتوى الملف كاملاً كنصّ واحد. <code>file.readlines()</code> تقرأ الملف كقائمة من الأسطر، كل عنصر سطر منفصل. للملفات الكبيرة، الأفضل التكرار مباشرة على الملف بحلقة <code>for line in file:</code> — تقرأ سطراً واحداً في كل دورة دون تحميل الملف كاملاً في الذاكرة دفعة واحدة.</p>

<h3>الصيغة الآمنة: with</h3>

<p>الطريقة الاحترافية الوحيدة تقريباً لفتح ملف هي <code>with open(filename) as file:</code>. لماذا؟ لأن الملف <strong>يجب</strong> أن يُغلق بعد الانتهاء منه (لتحرير الموارد، وضمان حفظ ما كُتب فعلياً على القرص). صيغة <code>with</code> تُغلق الملف تلقائياً حتى لو حدث خطأ أثناء العمل معه — بخلاف <code>open()</code> بمفردها التي تتطلّب تذكّر <code>file.close()</code> يدوياً، وهو ما ينساه الجميع عاجلاً أم آجلاً.</p>

<h3>الكتابة إلى ملف</h3>

<p><code>file.write(text)</code> تكتب نصاً إلى الملف — لا تضيف سطراً جديداً تلقائياً كما يفعل <code>print()</code>، فيجب إضافة <code>\\n</code> يدوياً إن أردت أسطراً منفصلة.</p>

<h3>أخطاء شائعة</h3>

<p>فتح ملف غير موجود بوضع <code>"r"</code> يرمي <code>FileNotFoundError</code> فوراً. وفتح ملف موجود بوضع <code>"w"</code> بالخطأ يمحو محتواه بالكامل بصمت دون أي تحذير — تحقّق دائماً من الوضع الصحيح قبل الكتابة.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li><code>open(filename, mode)</code>: <code>"r"</code> قراءة، <code>"w"</code> كتابة (يمحو الموجود)، <code>"a"</code> إضافة</li>
    <li>استخدم <code>with open(...) as file:</code> دائماً — تُغلق الملف تلقائياً وبأمان</li>
    <li><code>for line in file:</code> أفضل طريقة لقراءة ملف كبير سطراً بسطر</li>
    <li><code>file.write(text)</code> لا تضيف سطراً جديداً — أضف <code>\\n</code> يدوياً</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>اكتب برنامجاً يُنشئ ملف <code>notes.txt</code> ويكتب فيه ثلاثة أسطر بـ <code>with</code> ووضع <code>"w"</code>. ثم افتحه مجدداً بوضع القراءة واطبع كل سطر بحلقة <code>for</code>.</p>
`,
        en: `<p>Use open(filename, mode) to work with files: "r" reads, "w" writes (erasing existing content), "a" appends. Always use with open(...) as file: so the file closes automatically and safely, even if an error occurs. write() does not add a newline automatically.</p>`
    },
    code: `<span class="cm"># الكتابة إلى ملف — with يغلقه تلقائياً</span>
<span class="kw">with</span> <span class="fn">open</span>(<span class="st">"notes.txt"</span>, <span class="st">"w"</span>) <span class="kw">as</span> file:
    file.write(<span class="st">"First note\\n"</span>)
    file.write(<span class="st">"Second note\\n"</span>)
    file.write(<span class="st">"Third note\\n"</span>)


<span class="cm"># القراءة الكاملة كنصّ واحد</span>
<span class="kw">with</span> <span class="fn">open</span>(<span class="st">"notes.txt"</span>, <span class="st">"r"</span>) <span class="kw">as</span> file:
    <span class="kw">content</span> = file.read()
    <span class="fn">print</span>(content)


<span class="cm"># الأفضل للملفات الكبيرة: قراءة سطراً بسطر</span>
<span class="kw">with</span> <span class="fn">open</span>(<span class="st">"notes.txt"</span>, <span class="st">"r"</span>) <span class="kw">as</span> file:
    <span class="kw">for</span> line <span class="kw">in</span> file:
        <span class="fn">print</span>(line.strip())   <span class="cm"># strip يزيل \\n الزائد</span>


<span class="cm"># الإضافة دون محو المحتوى السابق</span>
<span class="kw">with</span> <span class="fn">open</span>(<span class="st">"notes.txt"</span>, <span class="st">"a"</span>) <span class="kw">as</span> file:
    file.write(<span class="st">"Fourth note (appended)\\n"</span>)


<span class="cm"># خطأ شائع: ملف غير موجود</span>
<span class="cm"># with open("missing.txt", "r") as f:   ← FileNotFoundError</span>`,
    quiz: {
        q: {
            ar: "ما الفائدة الأساسية من استخدام with open(...) as file بدل open() مباشرة؟",
            en: "What is the main benefit of with open(...) as file over calling open() directly?"
        },
        options: {
            ar: [
                "يجعل القراءة أسرع بكثير",
                "يُغلق الملف تلقائياً وبأمان حتى لو حدث خطأ أثناء العمل معه",
                "يسمح بفتح أكثر من ملف في نفس الوقت فقط",
                "يمنع الملف من الكتابة عليه بالخطأ"
            ],
            en: [
                "It makes reading much faster",
                "It automatically and safely closes the file, even if an error occurs while working with it",
                "It only allows opening more than one file at once",
                "It prevents the file from being accidentally overwritten"
            ]
        },
        correct: 1,
        explanation: {
            ar: "with يضمن استدعاء file.close() تلقائياً بمجرد الخروج من الكتلة، سواء انتهى الكود بنجاح أو حدث خطأ في المنتصف — بخلاف open() المباشرة التي تتطلّب تذكّر الإغلاق يدوياً في كل مرة.",
            en: "with guarantees file.close() is called automatically once the block exits, whether the code finished successfully or an error occurred midway — unlike calling open() directly, which requires remembering to close manually every time."
        }
    }
},

/* ---------- الدرس 29 ---------- */
{
    title: { ar: "العمل مع CSV وJSON", en: "Working with CSV and JSON" },
    body: {
        ar: `
<p>ملفات النصّ العادي (txt) رائعة للملاحظات البسيطة، لكن البيانات الحقيقية غالباً <strong>مُهيكَلة</strong>: جداول بأعمدة (كملف Excel)، أو بيانات متداخلة (كإعدادات تطبيق). هنا يأتي دور صيغتين معياريتين شائعتين جداً: <strong>CSV</strong> للجداول، و<strong>JSON</strong> للبيانات المتداخلة — وكلاهما مدعوم مباشرة بمكتبات جاهزة في بايثون.</p>

<h3>CSV: القيم المفصولة بفواصل</h3>

<p>ملف CSV (Comma-Separated Values) هو نصّ عادي، كل سطر فيه صفّ، والقيم مفصولة بفواصل. مكتبة <code>csv</code> المدمجة تُبسّط قراءته وكتابته: <code>csv.reader(file)</code> تُرجع كل صفّ كقائمة، و<code>csv.writer(file)</code> تكتب صفوفاً جديدة بـ <code>writerow(list)</code> دون القلق يدوياً بشأن الفواصل أو علامات التنصيص داخل البيانات.</p>

<h3>JSON: تبادل البيانات المتداخلة</h3>

<p>JSON (JavaScript Object Notation) صار المعيار العالمي لتبادل البيانات بين البرامج والخدمات على الويب. بنيته تُشبه تماماً قواميس وقوائم بايثون المتداخلة. مكتبة <code>json</code> المدمجة توفّر دالتين أساسيتين: <code>json.dump(data, file)</code> تكتب بيانات بايثون (قاموس أو قائمة) كملف JSON، و<code>json.load(file)</code> تقرأ ملف JSON وتحوّله مباشرة لقاموس أو قائمة بايثون حقيقية جاهزة للاستخدام.</p>

<h3>لماذا JSON مهم بهذا الشكل؟</h3>

<p>التحويل التلقائي بين هياكل بايثون وJSON يعني أنك تستطيع حفظ قاموس معقّد (كإعدادات تطبيق كاملة، أو بيانات مستخدم) بسطر واحد <code>json.dump()</code>، واسترجاعه لاحقاً بسطر واحد <code>json.load()</code>، دون كتابة أي منطق تحويل يدوي بنفسك.</p>

<h3>أخطاء شائعة</h3>

<p>الخلط بين <code>json.dump()</code> (تكتب لملف مفتوح) وبين <code>json.dumps()</code> (بحرف s إضافي — تُرجع نصّاً JSON كسلسلة نصية عادية، بلا كتابة لملف). نفس الفرق بين <code>json.load()</code> و<code>json.loads()</code>. وفتح ملف CSV بدون <code>newline=""</code> على ويندوز قد ينتج أسطراً فارغة زائدة بين الصفوف.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>CSV صيغة جدولية بسيطة، تتعامل معها مكتبة <code>csv</code> المدمجة</li>
    <li>JSON صيغة متداخلة تُطابق قواميس وقوائم بايثون تماماً</li>
    <li><code>json.dump(data, file)</code> يكتب، و<code>json.load(file)</code> يقرأ ويحوّل تلقائياً</li>
    <li>انتبه للفرق بين <code>dump/load</code> (ملف) و<code>dumps/loads</code> (نصّ)</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>أنشئ قاموساً بمعلومات كتاب (عنوان، مؤلف، سنة). احفظه في ملف <code>book.json</code> بـ <code>json.dump()</code>، ثم افتح الملف واقرأه مجدداً بـ <code>json.load()</code> واطبع كل قيمة.</p>
`,
        en: `<p>The csv module reads/writes tabular data with csv.reader() and csv.writer(). The json module converts Python dicts/lists to and from JSON files directly: json.dump(data, file) writes, json.load(file) reads and reconstructs the original structure automatically.</p>`
    },
    code: `<span class="cm"># CSV: الكتابة</span>
<span class="kw">import</span> csv

<span class="kw">with</span> <span class="fn">open</span>(<span class="st">"students.csv"</span>, <span class="st">"w"</span>, newline=<span class="st">""</span>) <span class="kw">as</span> file:
    <span class="kw">writer</span> = csv.writer(file)
    writer.writerow([<span class="st">"name"</span>, <span class="st">"grade"</span>])
    writer.writerow([<span class="st">"Sarah"</span>, 95])
    writer.writerow([<span class="st">"Ahmed"</span>, 88])


<span class="cm"># CSV: القراءة — كل صفّ يعود كقائمة</span>
<span class="kw">with</span> <span class="fn">open</span>(<span class="st">"students.csv"</span>, <span class="st">"r"</span>) <span class="kw">as</span> file:
    <span class="kw">reader</span> = csv.reader(file)
    <span class="kw">for</span> row <span class="kw">in</span> reader:
        <span class="fn">print</span>(row)


<span class="cm"># JSON: الكتابة من قاموس بايثون مباشرة</span>
<span class="kw">import</span> json

<span class="kw">book</span> = {<span class="st">"title"</span>: <span class="st">"Python Basics"</span>, <span class="st">"year"</span>: 2026, <span class="st">"tags"</span>: [<span class="st">"beginner"</span>, <span class="st">"programming"</span>]}

<span class="kw">with</span> <span class="fn">open</span>(<span class="st">"book.json"</span>, <span class="st">"w"</span>) <span class="kw">as</span> file:
    json.dump(book, file)


<span class="cm"># JSON: القراءة — تعود كقاموس بايثون جاهز</span>
<span class="kw">with</span> <span class="fn">open</span>(<span class="st">"book.json"</span>, <span class="st">"r"</span>) <span class="kw">as</span> file:
    <span class="kw">loaded_book</span> = json.load(file)

<span class="fn">print</span>(loaded_book[<span class="st">"title"</span>])   <span class="cm"># Python Basics</span>
<span class="fn">print</span>(<span class="fn">type</span>(loaded_book))       <span class="cm"># &lt;class 'dict'&gt;</span>`,
    quiz: {
        q: {
            ar: "ما الفرق بين json.dump() وjson.dumps()؟",
            en: "What is the difference between json.dump() and json.dumps()?"
        },
        options: {
            ar: [
                "لا فرق، الاسمان يؤديان نفس الشيء",
                "dump تكتب مباشرة لملف مفتوح، وdumps تُرجع نصّ JSON كسلسلة نصية",
                "dumps فقط تعمل مع القوائم",
                "dump أبطأ من dumps بكثير"
            ],
            en: [
                "No difference, both do the same thing",
                "dump writes directly to an open file, dumps returns a JSON string",
                "dumps only works with lists",
                "dump is much slower than dumps"
            ]
        },
        correct: 1,
        explanation: {
            ar: "dump() تحتاج كائن ملف مفتوح وتكتب إليه مباشرة، بينما dumps() (بحرف s للدلالة على 'string') لا تحتاج ملفاً أصلاً وتُرجع النتيجة كسلسلة نصية عادية يمكن استخدامها في أي مكان، مثل إرسالها عبر الشبكة.",
            en: "dump() needs an open file object and writes to it directly, while dumps() (the 's' stands for 'string') needs no file at all and returns the result as a plain string usable anywhere, like sending it over a network."
        }
    }
},

/* ---------- الدرس 30 ---------- */
{
    title: { ar: "التعامل مع الأخطاء: try/except", en: "Handling errors: try/except" },
    body: {
        ar: `
<p>في دروس سابقة، رأيت أخطاء كثيرة: <code>ValueError</code> عند تحويل نصّ غير رقمي، <code>FileNotFoundError</code> عند فتح ملف غير موجود، <code>ZeroDivisionError</code> عند القسمة على صفر. حتى الآن، أي من هذه الأخطاء كانت <strong>توقف البرنامج بالكامل فوراً</strong>. لكن البرامج الاحترافية لا تتوقّف بهذه السهولة — تتوقّع الأخطاء وتتعامل معها بأناقة. هذا هو دور <code>try/except</code>.</p>

<h3>البنية الأساسية</h3>

<p>ضع الكود الذي قد يفشل داخل كتلة <code>try:</code>. إن حدث خطأ بالفعل، يتوقّف تنفيذ <code>try</code> فوراً وينتقل البرنامج إلى كتلة <code>except:</code> المطابقة بدل التوقّف الكامل. إن لم يحدث أي خطأ، تُتجاهل كتلة <code>except</code> بالكامل ويكمل البرنامج طبيعياً بعدها.</p>

<h3>التقاط نوع خطأ محدد</h3>

<p>الأفضل دائماً تحديد نوع الخطأ المتوقّع صراحة: <code>except ValueError:</code> بدل <code>except:</code> عامة بلا تحديد. لماذا؟ لأن <code>except:</code> العامة تُخفي <strong>كل</strong> الأخطاء، حتى تلك غير المتوقّعة التي قد تكشف عن خطأ حقيقي في برنامجك يجب أن تراه وتصلحه، لا أن تُخفيه بصمت.</p>

<h3>عدة كتل except لأخطاء مختلفة</h3>

<p>يمكن وضع أكثر من كتلة <code>except</code> لأنواع أخطاء مختلفة، كل واحدة تتعامل مع حالتها الخاصة: <code>except ValueError:</code> لخطأ تحويل، ثم <code>except ZeroDivisionError:</code> لخطأ قسمة، بترتيب من الأكثر تحديداً للأعمّ.</p>

<h3>finally: كود يُنفَّذ دائماً</h3>

<p>كتلة <code>finally:</code> اختيارية تُنفَّذ <strong>دائماً</strong> بعد <code>try/except</code>، سواء نجح الكود أو فشل — مفيدة لعمليات تنظيف يجب أن تحدث دوماً، مثل إغلاق اتصال أو ملف (رغم أن <code>with</code> يغني عن هذا غالباً في حالة الملفات تحديداً).</p>

<h3>أخطاء شائعة</h3>

<p>استخدام <code>except:</code> عامة جداً تُخفي أخطاء حقيقية في الكود بدل الأخطاء المتوقّعة فقط. وكذلك وضع منطق كثير جداً داخل <code>try</code> بحيث تصعب معرفة أي سطر بالضبط سبّب الخطأ — اجعل كتلة <code>try</code> مركّزة على السطر أو السطرين المتوقّع فشلهما فقط.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li><code>try/except</code> يمنع توقّف البرنامج المفاجئ عند حدوث خطأ متوقّع</li>
    <li>حدّد نوع الخطأ صراحة: <code>except ValueError:</code> بدل <code>except:</code> عامة</li>
    <li>يمكن وضع عدة كتل <code>except</code> لأنواع أخطاء مختلفة</li>
    <li><code>finally:</code> يُنفَّذ دائماً، نجح الكود أو فشل</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>اكتب برنامجاً يطلب من المستخدم رقمين ويقسم الأول على الثاني، محاطاً بـ <code>try/except</code> يلتقط كلاً من <code>ValueError</code> (إدخال غير رقمي) و<code>ZeroDivisionError</code> (القسمة على صفر) برسالة واضحة لكل حالة.</p>
`,
        en: `<p>try/except prevents a program from crashing on expected errors: put risky code in try:, and handle specific failures in except ErrorType: blocks. Prefer specific exception types over a bare except: so real bugs aren't silently hidden. finally: always runs, whether an error occurred or not.</p>`
    },
    code: `<span class="cm"># بدون try/except — يتوقف البرنامج فوراً</span>
<span class="cm"># age = int(input("Age: "))   ← لو كتب المستخدم نصاً، ValueError يوقف كل شيء</span>


<span class="cm"># مع try/except — يتعافى بأناقة</span>
<span class="kw">try</span>:
    <span class="kw">age</span> = <span class="fn">int</span>(<span class="fn">input</span>(<span class="st">"Age: "</span>))
    <span class="fn">print</span>(<span class="st">f"You are {age} years old"</span>)
<span class="kw">except</span> <span class="fn">ValueError</span>:
    <span class="fn">print</span>(<span class="st">"That's not a valid number"</span>)


<span class="cm"># عدة كتل except لأخطاء مختلفة</span>
<span class="kw">try</span>:
    <span class="kw">num1</span> = <span class="fn">float</span>(<span class="fn">input</span>(<span class="st">"First number: "</span>))
    <span class="kw">num2</span> = <span class="fn">float</span>(<span class="fn">input</span>(<span class="st">"Second number: "</span>))
    <span class="kw">result</span> = num1 / num2
    <span class="fn">print</span>(<span class="st">f"Result: {result}"</span>)
<span class="kw">except</span> <span class="fn">ValueError</span>:
    <span class="fn">print</span>(<span class="st">"Please enter valid numbers"</span>)
<span class="kw">except</span> <span class="fn">ZeroDivisionError</span>:
    <span class="fn">print</span>(<span class="st">"Cannot divide by zero"</span>)


<span class="cm"># finally: يُنفَّذ دائماً</span>
<span class="kw">try</span>:
    <span class="kw">value</span> = <span class="fn">int</span>(<span class="st">"not a number"</span>)
<span class="kw">except</span> <span class="fn">ValueError</span>:
    <span class="fn">print</span>(<span class="st">"Conversion failed"</span>)
<span class="kw">finally</span>:
    <span class="fn">print</span>(<span class="st">"This always runs"</span>)`,
    quiz: {
        q: {
            ar: "لماذا يُفضَّل except ValueError: على except: عامة بلا تحديد؟",
            en: "Why is except ValueError: preferred over a bare except:?"
        },
        options: {
            ar: [
                "except: العامة أبطأ بكثير في التنفيذ",
                "except: العامة تُخفي كل أنواع الأخطاء، حتى الأخطاء الحقيقية غير المتوقّعة في الكود",
                "except ValueError: هي الصيغة الوحيدة الصحيحة في بايثون",
                "لا فرق فعلي بينهما"
            ],
            en: [
                "A bare except: is much slower to run",
                "A bare except: hides every kind of error, even real unexpected bugs in the code",
                "except ValueError: is the only valid syntax in Python",
                "There's no real difference between them"
            ]
        },
        correct: 1,
        explanation: {
            ar: "تحديد نوع الخطأ صراحة يعني أنك تلتقط فقط الحالة التي توقّعتها وتعرف كيف تتعامل معها. except: العامة تلتقط كل شيء، بما فيها أخطاء برمجية حقيقية (كخطأ إملائي في اسم متغيّر) يجب أن تراها وتصلحها، لا أن تختفي بصمت.",
            en: "Naming the exception type explicitly means you only catch the case you anticipated and know how to handle. A bare except: catches everything, including real bugs (like a typo in a variable name) that you should see and fix, not have silently swallowed."
        }
    }
},

/* ---------- الدرس 31 ---------- */
{
    title: { ar: "raise والتحقّق المسبق من الأخطاء", en: "raise and validating input proactively" },
    body: {
        ar: `
<p>حتى الآن، تعاملت مع أخطاء يرميها بايثون تلقائياً. لكن أحياناً تريد أنت نفسك أن تُوقف تنفيذ دالة وتُبلغ بخطأ واضح عندما يكون الإدخال غير منطقي حسب قواعد برنامجك الخاصة — حتى لو لم يكن هذا خطأ بايثون نفسه. هنا تستخدم <code>raise</code> لرمي خطأ يدوياً بنفسك.</p>

<h3>رمي خطأ بـ raise</h3>

<p>الصيغة: <code>raise ErrorType("رسالة توضيحية")</code>. مثال: دالة تحسب عمراً من سنة الميلاد يجب أن ترمي خطأ إن كانت السنة مستقبلية أو سالبة — حتى لو كانت السنة نفسها رقماً صالحاً تقنياً. <code>raise ValueError("Year cannot be negative")</code> يوقف الدالة فوراً برسالة واضحة تشرح <strong>لماذا</strong> فشلت العملية.</p>

<h3>لماذا نتحقّق يدوياً بدل انتظار الخطأ؟</h3>

<p>بايثون لا يعرف قواعد عملك الخاصة. عمر سالب رقم صالح تقنياً في بايثون (لن يرمي خطأ تلقائياً)، لكنه غير منطقي في سياق برنامجك. التحقّق اليدوي بـ <code>raise</code> يحوّل أخطاء منطقية صامتة (نتائج غريبة بلا تفسير) إلى أخطاء واضحة تُكتشف فوراً بدل أن تنتشر بصمت في بقية البرنامج.</p>

<h3>التقاط الأخطاء المُرمية يدوياً</h3>

<p>الخطأ المرمي بـ <code>raise</code> يُلتقط تماماً بنفس <code>try/except</code> الذي تعلمته: <code>except ValueError as e:</code> يلتقط الخطأ ويخزّن رسالته في <code>e</code>، يمكن طباعتها بـ <code>print(e)</code> لعرض رسالتك الخاصة للمستخدم مباشرة.</p>

<h3>مبدأ "افشل بسرعة ووضوح"</h3>

<p>هذه فلسفة برمجية مهمة: من الأفضل أن يتوقّف برنامجك برسالة خطأ واضحة فوراً عند إدخال غير منطقي، بدل أن يستمرّ بصمت وينتج نتائج خاطئة يصعب تتبّع مصدرها لاحقاً. التحقّق المبكر بـ <code>raise</code> يطبّق هذا المبدأ مباشرة.</p>

<h3>أخطاء شائعة</h3>

<p>رمي خطأ بلا رسالة توضيحية: <code>raise ValueError()</code> بلا نصّ يترك المستخدم (وأنت لاحقاً) بلا فكرة عن سبب المشكلة الفعلي. اكتب دائماً رسالة واضحة تشرح ماذا كان خاطئاً بالضبط.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li><code>raise ErrorType("رسالة")</code> يرمي خطأً يدوياً حسب قواعد برنامجك الخاصة</li>
    <li>يُستخدم للتحقّق من إدخال صالح تقنياً في بايثون لكنه غير منطقي في سياقك</li>
    <li>يُلتقط بنفس <code>try/except</code>، مع <code>as e</code> للوصول لرسالة الخطأ</li>
    <li>اكتب دائماً رسالة توضيحية واضحة تشرح سبب الفشل بالضبط</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>اكتب دالة <code>set_age(age)</code> ترمي <code>ValueError</code> برسالة واضحة إن كان العمر سالباً أو أكبر من 120، وإلا تطبع "Age set successfully". اختبرها بقيم صالحة وغير صالحة داخل <code>try/except</code>.</p>
`,
        en: `<p>Use raise ErrorType("message") to manually stop execution when input is technically valid in Python but doesn't make sense for your program's rules — like a negative age. It's caught with the same try/except, using except ErrorType as e: to access the message via print(e).</p>`
    },
    code: `<span class="cm"># رمي خطأ يدوياً عند إدخال غير منطقي</span>
<span class="kw">def</span> set_age(age):
    <span class="kw">if</span> age < 0 <span class="kw">or</span> age > 120:
        <span class="kw">raise</span> <span class="fn">ValueError</span>(<span class="st">"Age must be between 0 and 120"</span>)
    <span class="fn">print</span>(<span class="st">f"Age set to {age}"</span>)


<span class="cm"># التقاط الخطأ المرمي يدوياً — نفس try/except المعتاد</span>
<span class="kw">try</span>:
    set_age(-5)
<span class="kw">except</span> <span class="fn">ValueError</span> <span class="kw">as</span> e:
    <span class="fn">print</span>(<span class="st">f"Error: {e}"</span>)   <span class="cm"># يطبع رسالتك الخاصة</span>


<span class="cm"># مثال آخر: التحقّق قبل قسمة منطقية</span>
<span class="kw">def</span> calculate_average(scores):
    <span class="kw">if</span> <span class="fn">len</span>(scores) == 0:
        <span class="kw">raise</span> <span class="fn">ValueError</span>(<span class="st">"Cannot calculate average of an empty list"</span>)
    <span class="kw">return</span> <span class="fn">sum</span>(scores) / <span class="fn">len</span>(scores)

<span class="kw">try</span>:
    <span class="fn">print</span>(calculate_average([]))
<span class="kw">except</span> <span class="fn">ValueError</span> <span class="kw">as</span> e:
    <span class="fn">print</span>(<span class="st">f"Error: {e}"</span>)


<span class="cm"># حالة ناجحة — لا خطأ يُرمى إطلاقاً</span>
<span class="kw">try</span>:
    set_age(25)
<span class="kw">except</span> <span class="fn">ValueError</span> <span class="kw">as</span> e:
    <span class="fn">print</span>(<span class="st">f"Error: {e}"</span>)`,
    quiz: {
        q: {
            ar: "متى تستخدم raise بدل انتظار خطأ بايثون التلقائي؟",
            en: "When would you use raise instead of waiting for an automatic Python error?"
        },
        options: {
            ar: [
                "raise أسرع دائماً من الأخطاء التلقائية",
                "عندما تكون القيمة صالحة تقنياً في بايثون لكنها غير منطقية حسب قواعد برنامجك الخاصة",
                "raise تعمل فقط داخل الدوال",
                "لا داعٍ لاستخدام raise أبداً، بايثون يكتشف كل الأخطاء تلقائياً"
            ],
            en: [
                "raise is always faster than automatic errors",
                "When a value is technically valid in Python but doesn't make sense per your program's own rules",
                "raise only works inside functions",
                "There's never a need to use raise, Python catches every error automatically"
            ]
        },
        correct: 1,
        explanation: {
            ar: "بايثون يرمي أخطاء فقط على مستوى اللغة نفسها (كتحويل نصّ غير رقمي). عمر سالب أو قائمة فارغة عند حساب متوسّط قيم صالحة تقنياً في بايثون، لكنها غير منطقية في سياق برنامجك — وهنا raise يفرض قواعدك الخاصة صراحة.",
            en: "Python only raises errors at the language level itself (like converting a non-numeric string). A negative age or an empty list when averaging are technically valid Python values, but don't make sense in your program's context — that's exactly where raise enforces your own rules explicitly."
        }
    }
},

/* ---------- الدرس 32 — مشروع ---------- */
{
    title: { ar: "مشروع 5: مدير مهام", en: "Project 5: Task manager" },
    body: {
        ar: `
<p>مشروع هذا المستوى يجمع كل ما تعلمته: قراءة وكتابة الملفات، JSON، وtry/except. ستبني مدير مهام يحفظ بياناته في ملف JSON حقيقي، فتبقى المهام محفوظة حتى بعد إغلاق البرنامج وإعادة تشغيله — أول مشروع في هذا المسار ببيانات <strong>دائمة</strong> فعلاً.</p>

<h3>التحميل عند البدء، الحفظ عند التعديل</h3>

<p>الفكرة الأساسية: عند بدء البرنامج، حاول تحميل المهام من <code>tasks.json</code> إن كان موجوداً (بـ <code>try/except FileNotFoundError</code> — أول تشغيل لن يجد الملف أصلاً، وهذا متوقّع وليس خطأً حقيقياً). بعد أي تعديل (إضافة، إنجاز مهمة)، احفظ القائمة كاملة مجدداً إلى الملف بـ <code>json.dump()</code> فوراً.</p>

<h3>لماذا try/except هنا تحديداً منطقي جداً؟</h3>

<p>عدم وجود ملف <code>tasks.json</code> عند أول تشغيل ليس خللاً في البرنامج — إنه الحالة الطبيعية المتوقّعة تماماً. بدل أن يتوقّف البرنامج بخطأ مرعب لأول مستخدم يجرّبه، يلتقط <code>except FileNotFoundError</code> هذه الحالة بأناقة ويبدأ بقائمة فارغة كأنه أمر طبيعي — لأنه فعلاً كذلك.</p>

<h3>هيكل بيانات كل مهمة</h3>

<p>كل مهمة قاموس: <code>{"title": "...", "done": False}</code>. هذا يسمح لاحقاً بتوسيع كل مهمة بحقول إضافية (تاريخ استحقاق، أولوية) دون تغيير بنية الملف بالكامل — نفس نمط قائمة القواميس من مشروع دفتر جهات الاتصال.</p>

<h3>تحديات للتوسيع</h3>

<ul>
    <li>أضف خيار حذف مهمة، مع حفظ الملف فوراً بعد الحذف</li>
    <li>أضف تاريخ إنشاء لكل مهمة باستخدام مكتبة <code>datetime</code></li>
    <li>اعرض عدد المهام المنجزة مقابل الكلي عند بدء البرنامج</li>
    <li>تعامل أيضاً مع خطأ <code>json.JSONDecodeError</code> إن كان الملف موجوداً لكن تالفاً</li>
</ul>

<h3>ماذا أنجزت في هذا المستوى؟</h3>

<ul>
    <li>قرأت من الملفات وكتبت إليها بأمان باستخدام <code>with</code></li>
    <li>خزّنت بيانات مُهيكَلة حقيقية بصيغتي CSV وJSON، وحوّلتها تلقائياً من وإلى بنى بايثون</li>
    <li>تعاملت مع الأخطاء المتوقّعة بأناقة بـ <code>try/except</code> بدل توقّف البرنامج المفاجئ</li>
    <li>رميت أخطاءك الخاصة بـ <code>raise</code> عند إدخال غير منطقي حسب قواعدك</li>
    <li>وبنيت أول برنامج ببيانات <strong>دائمة</strong> فعلاً تبقى بعد إغلاق البرنامج</li>
</ul>

<p>في المستوى السادس سنتعلّم البرمجة الكائنية (OOP) — طريقة تنظيم أكبر بكثير لتمثيل أشياء حقيقية في الكود، بدل قواميس وقوائم منفصلة عن بعضها.</p>
`,
        en: `<p>This project combines file I/O, JSON, and try/except into a persistent task manager: tasks load from tasks.json on start (missing file on first run is caught gracefully, not treated as a crash) and save back after every change — the first project in this path with real persistent data.</p>`
    },
    code: `<span class="cm"># ============================================</span>
<span class="cm"># مدير مهام مع حفظ دائم</span>
<span class="cm"># ============================================</span>
<span class="kw">import</span> json

<span class="kw">FILENAME</span> = <span class="st">"tasks.json"</span>


<span class="kw">def</span> load_tasks():
    <span class="kw">try</span>:
        <span class="kw">with</span> <span class="fn">open</span>(FILENAME, <span class="st">"r"</span>) <span class="kw">as</span> file:
            <span class="kw">return</span> json.load(file)
    <span class="kw">except</span> <span class="fn">FileNotFoundError</span>:
        <span class="kw">return</span> []   <span class="cm"># أول تشغيل — لا يوجد ملف بعد، وهذا طبيعي</span>


<span class="kw">def</span> save_tasks(tasks):
    <span class="kw">with</span> <span class="fn">open</span>(FILENAME, <span class="st">"w"</span>) <span class="kw">as</span> file:
        json.dump(tasks, file)


<span class="kw">tasks</span> = load_tasks()
<span class="fn">print</span>(<span class="st">f"Loaded {len(tasks)} task(s)"</span>)

<span class="kw">while</span> <span class="kw">True</span>:
    <span class="fn">print</span>(<span class="st">"\\n1) Add  2) Complete  3) List  4) Exit"</span>)
    <span class="kw">choice</span> = <span class="fn">input</span>(<span class="st">"Choose an option: "</span>).strip()

    <span class="kw">if</span> choice == <span class="st">"1"</span>:
        <span class="kw">title</span> = <span class="fn">input</span>(<span class="st">"Task title: "</span>)
        tasks.append({<span class="st">"title"</span>: title, <span class="st">"done"</span>: <span class="kw">False</span>})
        save_tasks(tasks)

    <span class="kw">elif</span> choice == <span class="st">"2"</span>:
        <span class="kw">for</span> i, task <span class="kw">in</span> <span class="fn">enumerate</span>(tasks):
            <span class="fn">print</span>(<span class="st">f"{i}. {task['title']}"</span>)
        <span class="kw">try</span>:
            <span class="kw">index</span> = <span class="fn">int</span>(<span class="fn">input</span>(<span class="st">"Task number: "</span>))
            tasks[index][<span class="st">"done"</span>] = <span class="kw">True</span>
            save_tasks(tasks)
        <span class="kw">except</span> (<span class="fn">ValueError</span>, <span class="fn">IndexError</span>):
            <span class="fn">print</span>(<span class="st">"Invalid task number"</span>)

    <span class="kw">elif</span> choice == <span class="st">"3"</span>:
        <span class="kw">for</span> task <span class="kw">in</span> tasks:
            <span class="kw">status</span> = <span class="st">"[x]"</span> <span class="kw">if</span> task[<span class="st">"done"</span>] <span class="kw">else</span> <span class="st">"[ ]"</span>
            <span class="fn">print</span>(<span class="st">f"{status} {task['title']}"</span>)

    <span class="kw">elif</span> choice == <span class="st">"4"</span>:
        <span class="fn">print</span>(<span class="st">"Goodbye!"</span>)
        <span class="kw">break</span>`,
    quiz: {
        q: {
            ar: "لماذا لا يُعتبر FileNotFoundError عند تحميل tasks.json خطأً حقيقياً في هذا المشروع؟",
            en: "Why isn't FileNotFoundError when loading tasks.json treated as a real error in this project?"
        },
        options: {
            ar: [
                "لأن بايثون لا يرمي هذا الخطأ أصلاً في هذه الحالة",
                "لأنها حالة متوقّعة تماماً عند أول تشغيل قبل إنشاء أي مهمة، ويجب معالجتها ببداية بقائمة فارغة",
                "لأن json.load() لا تحتاج ملفاً موجوداً أصلاً",
                "لأن try/except يمنع حدوث الخطأ من الأساس"
            ],
            en: [
                "Because Python doesn't actually raise this error in this case",
                "Because it's a fully expected case on first run before any task exists, handled by starting with an empty list",
                "Because json.load() doesn't actually need an existing file",
                "Because try/except prevents the error from happening at all"
            ]
        },
        correct: 1,
        explanation: {
            ar: "عند أول تشغيل، لم يُنشَأ tasks.json بعد — هذا متوقّع تماماً وليس خللاً في البرنامج. except FileNotFoundError يلتقط هذه الحالة الطبيعية تحديداً ويبدأ بقائمة فارغة بدل توقّف البرنامج بخطأ مرعب لأول مستخدم.",
            en: "On first run, tasks.json hasn't been created yet — this is entirely expected, not a program bug. except FileNotFoundError catches exactly this normal case and starts with an empty list instead of crashing with a scary error for the very first user."
        }
    }
}
,

/* ---------- الدرس 33 ---------- */
{
    title: { ar: "الأصناف والكائنات: أول خطوة في OOP", en: "Classes and objects: your first step into OOP" },
    body: {
        ar: `
<p>تذكّر مشروع دفتر جهات الاتصال: كل جهة اتصال كانت قاموساً <code>{"name": "...", "phone": "..."}</code>. هذا يعمل، لكن لا شيء يربط البيانات بسلوكها. ماذا لو أردت أن "تعرف" كل جهة اتصال كيف تعرّف عن نفسها؟ <strong>البرمجة الكائنية (OOP)</strong> تحلّ هذا: تجمع البيانات (attributes) والسلوك (methods) المرتبطين بها معاً في قالب واحد يُسمّى <strong>الصنف (class)</strong>.</p>

<h3>الصنف قالب، والكائن نسخة منه</h3>

<p>فكّر في الصنف كقالب معجّنات: يحدّد الشكل، لكنه ليس معجّنة فعلية. <strong>الكائن (object/instance)</strong> هو المعجّنة الفعلية المصنوعة من ذلك القالب. يمكنك صنع عشرات الكائنات من نفس الصنف، لكل منها بياناته الخاصة، بنفس السلوك المُعرَّف مرة واحدة في الصنف.</p>

<h3>تعريف صنف بسيط</h3>

<p>يُعرَّف الصنف بالكلمة <code>class</code> واسم يبدأ بحرف كبير عرفاً (اصطلاح مهم في بايثون): <code>class Contact:</code>. الدالة الخاصة <code>__init__</code> (تُنطق "دَندَر إينِت") هي <strong>المُنشئ (constructor)</strong> — تُنفَّذ تلقائياً عند إنشاء كائن جديد، وتُستخدم لتهيئة بياناته الأولية.</p>

<h3>self: الإشارة للكائن نفسه</h3>

<p>لاحظ أن كل دالة داخل الصنف تأخذ <code>self</code> كأول معامل دائماً. <code>self</code> هو مرجع للكائن الفعلي الذي يستدعي الدالة — يسمح لك بتخزين بيانات خاصة بهذا الكائن تحديداً: <code>self.name = name</code> يخزّن الاسم كخاصية (attribute) على هذا الكائن بالذات، منفصلة تماماً عن أي كائن آخر من نفس الصنف.</p>

<h3>إنشاء كائنات والوصول لخصائصها</h3>

<p>لإنشاء كائن: <code>contact1 = Contact("Sarah", "0612345678")</code> — هذا يستدعي <code>__init__</code> تلقائياً بهذه القيم. للوصول لخاصية: <code>contact1.name</code> — بنفس منطق الوصول لمفتاح قاموس، لكن بنقطة بدل قوسين مربّعين.</p>

<h3>أخطاء شائعة</h3>

<p>نسيان <code>self</code> كأول معامل في <code>__init__</code> أو أي دالة داخل الصنف يرمي خطأً. والخلط بين خاصية الصنف نفسها وخاصية الكائن — <code>self.name</code> خاصة بكل كائن على حدة، بينما متغيّر مُعرَّف مباشرة داخل الصنف (خارج أي دالة) مشترك بين كل الكائنات.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>الصنف قالب يجمع البيانات والسلوك معاً؛ الكائن نسخة فعلية منه</li>
    <li><code>__init__</code> مُنشئ يُنفَّذ تلقائياً عند إنشاء كائن جديد</li>
    <li><code>self</code> يشير للكائن نفسه، ويُستخدم لتخزين خصائصه الخاصة</li>
    <li>الوصول لخاصية كائن: <code>object.attribute</code></li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>عرّف صنف <code>Book</code> بخصائص title وauthor وyear في <code>__init__</code>. أنشئ كائنين مختلفين منه، واطبع بيانات كل كائن على حدة للتأكد من أن كل كائن يحتفظ ببياناته الخاصة منفصلة عن الآخر.</p>
`,
        en: `<p>A class is a template bundling data (attributes) and behavior (methods) together; an object is an actual instance created from it. __init__ runs automatically when a new object is created, and self refers to that specific object, letting you store per-object data with self.attribute = value.</p>`
    },
    code: `<span class="cm"># تعريف صنف بسيط</span>
<span class="kw">class</span> Contact:
    <span class="kw">def</span> __init__(self, name, phone):
        self.name = name     <span class="cm"># خاصية خاصة بكل كائن</span>
        self.phone = phone


<span class="cm"># إنشاء كائنين مختلفين من نفس الصنف</span>
<span class="kw">contact1</span> = Contact(<span class="st">"Sarah"</span>, <span class="st">"0612345678"</span>)
<span class="kw">contact2</span> = Contact(<span class="st">"Ahmed"</span>, <span class="st">"0698765432"</span>)


<span class="cm"># الوصول للخصائص — كل كائن يحتفظ ببياناته الخاصة</span>
<span class="fn">print</span>(contact1.name)    <span class="cm"># Sarah</span>
<span class="fn">print</span>(contact2.name)    <span class="cm"># Ahmed — منفصل تماماً</span>
<span class="fn">print</span>(<span class="st">f"{contact1.name}: {contact1.phone}"</span>)


<span class="cm"># نوع الكائن</span>
<span class="fn">print</span>(<span class="fn">type</span>(contact1))   <span class="cm"># &lt;class '__main__.Contact'&gt;</span>


<span class="cm"># خطأ شائع: نسيان self</span>
<span class="cm"># def __init__(name, phone):   ← سيُعامَل name كـ self بالخطأ!</span>`,
    quiz: {
        q: {
            ar: "ما وظيفة self داخل دوال الصنف؟",
            en: "What is the role of self inside a class's functions?"
        },
        options: {
            ar: [
                "اسم متغيّر عشوائي بلا معنى خاص",
                "يشير إلى الكائن الفعلي الذي يستدعي الدالة، ويُستخدم لتخزين خصائصه الخاصة",
                "يشير إلى الصنف نفسه، وليس الكائن",
                "مطلوب فقط في __init__، وليس بقية الدوال"
            ],
            en: [
                "A random variable name with no special meaning",
                "It refers to the actual object calling the function, used to store that object's own data",
                "It refers to the class itself, not the object",
                "It's only required in __init__, not other functions"
            ]
        },
        correct: 1,
        explanation: {
            ar: "self هو مرجع للكائن الفعلي الذي استُدعيت الدالة من خلاله. self.name = name يخزّن الاسم على هذا الكائن بالذات، فلا يتداخل مع بيانات أي كائن آخر من نفس الصنف. يجب أن يكون أول معامل في كل دالة داخل الصنف.",
            en: "self is a reference to the actual object the function was called through. self.name = name stores the name on that specific object, so it never interferes with any other object's data from the same class. It must be the first parameter in every function inside the class."
        }
    }
},

/* ---------- الدرس 34 ---------- */
{
    title: { ar: "الدوال داخل الأصناف (Methods)", en: "Methods: functions inside classes" },
    body: {
        ar: `
<p>الدرس السابق علّمك تخزين بيانات في كائن. لكن OOP الحقيقية تربط <strong>السلوك</strong> بالبيانات أيضاً — لا يكفي أن يخزّن الكائن اسمه وهاتفه، بل يجب أن "يعرف" كيف يطبع نفسه، أو كيف يقارن نفسه بكائن آخر. الدوال المُعرَّفة داخل صنف تُسمّى <strong>methods</strong>، وتعمل مباشرة على بيانات الكائن عبر <code>self</code>.</p>

<h3>تعريف method واستدعاؤها</h3>

<p>تُعرَّف method مثل أي دالة عادية، لكن داخل الصنف، وبـ <code>self</code> كأول معامل دائماً: <code>def introduce(self): return f"I'm {self.name}"</code>. تُستدعى على كائن محدّد بنقطة: <code>contact1.introduce()</code> — لاحظ أنك لا تمرّر <code>self</code> يدوياً عند الاستدعاء؛ بايثون تمرّره تلقائياً وتعني به الكائن الذي استدعيت الدالة عليه.</p>

<h3>Method تقرأ وتُعدّل خصائص الكائن</h3>

<p>داخل أي method، تستطيع قراءة خصائص الكائن (<code>self.name</code>) واستخدامها في حسابات أو نصوص، وأيضاً <strong>تعديلها</strong> مباشرة: <code>self.phone = new_phone</code> يغيّر رقم الهاتف لهذا الكائن تحديداً، دون التأثير على أي كائن آخر.</p>

<h3>Method تستدعي method أخرى</h3>

<p>يمكن لمethod أن تستدعي method أخرى من نفس الصنف عبر <code>self</code>: <code>self.other_method()</code>. هذا يسمح ببناء سلوك مركّب من قطع أصغر قابلة لإعادة الاستخدام داخل الصنف نفسه.</p>

<h3>الفرق بين method عادية ودالة عادية</h3>

<p>الفرق الجوهري: method مرتبطة بكائن محدّد عبر <code>self</code>، وتصل تلقائياً لبيانات ذلك الكائن دون الحاجة لتمريرها كمعاملات صريحة. دالة عادية خارج أي صنف لا تملك هذا الارتباط التلقائي بأي بيانات.</p>

<h3>أخطاء شائعة</h3>

<p>نسيان <code>self.</code> قبل خاصية داخل method — كتابة <code>name</code> بدل <code>self.name</code> تعني متغيّراً محلياً منفصلاً تماماً، غير مرتبط بالكائن، وغالباً يرمي <code>NameError</code> إن لم يكن مُعرَّفاً محلياً.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>Method دالة داخل صنف، بـ <code>self</code> كأول معامل دائماً</li>
    <li>تُستدعى على كائن محدّد: <code>object.method()</code>، بلا تمرير self يدوياً</li>
    <li>تصل لبيانات الكائن عبر <code>self.attribute</code>، قراءة أو تعديلاً</li>
    <li>يمكن لmethod استدعاء method أخرى من نفس الصنف عبر <code>self</code></li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>أضف للصنف <code>Book</code> من الدرس السابق method باسم <code>summary()</code> تُرجع جملة تصف الكتاب كاملة، وmethod أخرى <code>update_year(new_year)</code> تعدّل سنة النشر. اختبر الاثنتين على كائن حقيقي.</p>
`,
        en: `<p>Methods are functions defined inside a class, always taking self as the first parameter, and called on a specific object with object.method() — you never pass self manually. Inside a method, self.attribute reads or modifies that specific object's data.</p>`
    },
    code: `<span class="kw">class</span> Contact:
    <span class="kw">def</span> __init__(self, name, phone):
        self.name = name
        self.phone = phone

    <span class="cm"># method تقرأ بيانات الكائن</span>
    <span class="kw">def</span> introduce(self):
        <span class="kw">return</span> <span class="st">f"I'm {self.name}, call me at {self.phone}"</span>

    <span class="cm"># method تُعدّل بيانات الكائن</span>
    <span class="kw">def</span> update_phone(self, new_phone):
        self.phone = new_phone
        <span class="fn">print</span>(<span class="st">f"Phone updated for {self.name}"</span>)

    <span class="cm"># method تستدعي method أخرى عبر self</span>
    <span class="kw">def</span> full_details(self):
        <span class="kw">return</span> <span class="st">f"Contact card: {self.introduce()}"</span>


<span class="kw">contact1</span> = Contact(<span class="st">"Sarah"</span>, <span class="st">"0612345678"</span>)

<span class="fn">print</span>(contact1.introduce())
contact1.update_phone(<span class="st">"0699999999"</span>)
<span class="fn">print</span>(contact1.phone)          <span class="cm"># تغيّر فعلاً</span>
<span class="fn">print</span>(contact1.full_details())


<span class="cm"># خطأ شائع: نسيان self داخل الدالة</span>
<span class="cm"># def introduce(self):</span>
<span class="cm">#     return f"I'm {name}"   ← NameError: name غير معروف!</span>`,
    quiz: {
        q: {
            ar: "لماذا نستدعي contact1.introduce() بلا تمرير self صراحة رغم أن introduce تأخذ self كمعامل؟",
            en: "Why do we call contact1.introduce() without explicitly passing self, even though introduce takes self as a parameter?"
        },
        options: {
            ar: [
                "لأن introduce لا تحتاج self فعلياً هنا",
                "لأن بايثون تمرّر الكائن (contact1) تلقائياً كـ self عند الاستدعاء بصيغة النقطة",
                "لأن self معامل اختياري دائماً",
                "هذا خطأ فعلاً، والكود يجب أن يفشل"
            ],
            en: [
                "Because introduce doesn't actually need self here",
                "Because Python automatically passes the object (contact1) as self when called with dot syntax",
                "Because self is always an optional parameter",
                "This is actually an error, and the code should fail"
            ]
        },
        correct: 1,
        explanation: {
            ar: "عند استدعاء object.method()، بايثون تمرّر الكائن نفسه تلقائياً كأول معامل (self) خلف الكواليس. لهذا contact1.introduce() يكافئ فعلياً Contact.introduce(contact1)، لكن الصيغة الأولى أوضح وأشيع بكثير.",
            en: "When calling object.method(), Python automatically passes the object itself as the first argument (self) behind the scenes. So contact1.introduce() is effectively equivalent to Contact.introduce(contact1), but the first form is far clearer and far more common."
        }
    }
},

/* ---------- الدرس 35 ---------- */
{
    title: { ar: "الوراثة: بناء أصناف من أصناف أخرى", en: "Inheritance: building classes from other classes" },
    body: {
        ar: `
<p>تخيّل أنك تبني نظاماً لمكتبة: عندك كتب عادية، وكتب صوتية. كلاهما له عنوان ومؤلف، لكن الكتاب الصوتي له أيضاً مدّة تشغيل بالدقائق. هل تكتب صنفين منفصلين تماماً بتكرار كامل للعنوان والمؤلف؟ <strong>الوراثة (Inheritance)</strong> تحلّ هذا: يمكن لصنف جديد أن <strong>يرث</strong> كل خصائص وmethods صنف موجود، ثم يضيف أو يُعدّل ما يخصّه فقط.</p>

<h3>صنف أب وصنف ابن</h3>

<p>الصنف الأصلي يُسمّى <strong>الأب (parent/base class)</strong>، والصنف الوارث يُسمّى <strong>الابن (child/derived class)</strong>. صيغة الوراثة: <code>class AudioBook(Book):</code> — الابن بين قوسين بعد اسم الصنف الابن. تلقائياً، يمتلك <code>AudioBook</code> كل ما يملكه <code>Book</code> من خصائص وmethods، دون إعادة كتابتها.</p>

<h3>super(): استدعاء الأب من الابن</h3>

<p>داخل <code>__init__</code> الصنف الابن، تستدعي <code>super().__init__(...)</code> لتشغيل مُنشئ الأب أولاً (يهيّئ الخصائص المشتركة كالعنوان والمؤلف)، ثم تضيف خصائص الابن الخاصة بعدها مباشرة: <code>self.duration_minutes = duration_minutes</code>. هذا يتجنّب تكرار نفس منطق التهيئة في كل صنف ابن.</p>

<h3>Override: إعادة تعريف method في الابن</h3>

<p>يمكن للصنف الابن <strong>إعادة تعريف</strong> method موروثة من الأب بسلوك مختلف — يُسمّى هذا Override. مثلاً: <code>Book</code> لديه <code>summary()</code> تصف كتاباً عادياً، بينما <code>AudioBook</code> يعيد تعريف نفس الاسم <code>summary()</code> ليضيف مدّة التشغيل أيضاً. عند استدعاء <code>summary()</code> على كائن AudioBook، تُنفَّذ نسخة الابن، لا نسخة الأب.</p>

<h3>لماذا الوراثة مفيدة عملياً؟</h3>

<p>تمنع تكرار الكود بين أصناف مرتبطة منطقياً، وتُبسّط الصيانة: تعديل واحد في الصنف الأب ينعكس تلقائياً على كل الأصناف الوارثة منه. لكن احذر الإفراط فيها — وراثة عميقة جداً (أصناف ترث من أصناف ترث من أصناف) تُصعّب فهم الكود، لا تُسهّله.</p>

<h3>أخطاء شائعة</h3>

<p>نسيان استدعاء <code>super().__init__()</code> في الابن يعني أن خصائص الأب (كالعنوان والمؤلف) لن تُهيَّأ أصلاً. والخلط بين "الابن يرث من الأب" و"الأب يعرف عن الابن" — العلاقة اتجاه واحد فقط: الابن يعرف الأب، لكن الأب لا يعرف شيئاً عن أصنافه الوارثة.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>الوراثة: <code>class Child(Parent):</code> تمنح الابن كل ما يملكه الأب تلقائياً</li>
    <li><code>super().__init__(...)</code> يشغّل مُنشئ الأب أولاً من داخل الابن</li>
    <li>Override: إعادة تعريف method موروثة بسلوك مختلف في الصنف الابن</li>
    <li>الوراثة تمنع التكرار بين أصناف مرتبطة منطقياً</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>عرّف صنف <code>Book</code> بـ title وauthor وmethod <code>summary()</code>. عرّف صنف <code>EBook</code> يرث منه ويضيف خاصية <code>file_size_mb</code>، ويُعيد تعريف <code>summary()</code> لتضمين حجم الملف أيضاً.</p>
`,
        en: `<p>Inheritance lets a child class (class Child(Parent):) automatically gain everything from a parent class. Call super().__init__(...) inside the child to run the parent's constructor first, then add child-specific attributes. Overriding lets the child redefine a method with different behavior.</p>`
    },
    code: `<span class="cm"># الصنف الأب</span>
<span class="kw">class</span> Book:
    <span class="kw">def</span> __init__(self, title, author):
        self.title = title
        self.author = author

    <span class="kw">def</span> summary(self):
        <span class="kw">return</span> <span class="st">f"{self.title} by {self.author}"</span>


<span class="cm"># صنف ابن — يرث من Book</span>
<span class="kw">class</span> AudioBook(Book):
    <span class="kw">def</span> __init__(self, title, author, duration_minutes):
        <span class="fn">super</span>().__init__(title, author)   <span class="cm"># يهيّئ خصائص الأب أولاً</span>
        self.duration_minutes = duration_minutes    <span class="cm"># خاصية خاصة بالابن</span>

    <span class="cm"># Override: إعادة تعريف summary بسلوك مختلف</span>
    <span class="kw">def</span> summary(self):
        <span class="kw">base</span> = <span class="fn">super</span>().summary()
        <span class="kw">return</span> <span class="st">f"{base} ({self.duration_minutes} min audio)"</span>


<span class="kw">book</span> = Book(<span class="st">"Python Basics"</span>, <span class="st">"Sarah Ahmed"</span>)
<span class="kw">audio</span> = AudioBook(<span class="st">"Python Basics"</span>, <span class="st">"Sarah Ahmed"</span>, 240)

<span class="fn">print</span>(book.summary())    <span class="cm"># Python Basics by Sarah Ahmed</span>
<span class="fn">print</span>(audio.summary())   <span class="cm"># نفس النص + المدّة — النسخة المُعاد تعريفها</span>


<span class="cm"># الابن يملك خصائص الأب أيضاً تلقائياً</span>
<span class="fn">print</span>(audio.title)    <span class="cm"># Python Basics — موروث من Book</span>
<span class="fn">print</span>(<span class="fn">isinstance</span>(audio, Book))   <span class="cm"># True — AudioBook هو Book أيضاً</span>`,
    quiz: {
        q: {
            ar: "لماذا نستدعي super().__init__(...) داخل مُنشئ الصنف الابن؟",
            en: "Why do we call super().__init__(...) inside the child class's constructor?"
        },
        options: {
            ar: [
                "لحذف مُنشئ الأب نهائياً",
                "لتشغيل مُنشئ الصنف الأب وتهيئة خصائصه المشتركة، قبل إضافة خصائص الابن الخاصة",
                "هو معامل اختياري بلا تأثير حقيقي",
                "لجعل الصنف الأب يرث من الابن"
            ],
            en: [
                "To delete the parent's constructor entirely",
                "To run the parent class's constructor and initialize its shared attributes, before adding the child's own attributes",
                "It's an optional call with no real effect",
                "To make the parent class inherit from the child"
            ]
        },
        correct: 1,
        explanation: {
            ar: "super().__init__(...) يستدعي مُنشئ الأب صراحة، فتُهيَّأ الخصائص المشتركة (كالعنوان والمؤلف) بنفس منطق الأب دون تكرار كتابته في كل صنف ابن. بدونه، تلك الخصائص لن تُهيَّأ أصلاً في كائنات الابن.",
            en: "super().__init__(...) explicitly calls the parent's constructor, so shared attributes (like title and author) get initialized using the parent's own logic without rewriting it in every child class. Without it, those attributes would never get initialized on child objects at all."
        }
    }
},

/* ---------- الدرس 36 ---------- */
{
    title: { ar: "Encapsulation: حماية بيانات الكائن", en: "Encapsulation: protecting object data" },
    body: {
        ar: `
<p>حتى الآن، أي كود خارج الصنف يستطيع تعديل خصائص الكائن مباشرة: <code>contact1.phone = "invalid"</code> يعمل دون أي تحقّق، حتى لو كانت القيمة غير منطقية. <strong>Encapsulation</strong> مبدأ يحمي بيانات الكائن الداخلية من التعديل المباشر غير المُتحكَّم به، ويفرض المرور عبر methods مُصمَّمة للتحقّق أولاً.</p>

<h3>الاصطلاح: الشرطة السفلية الواحدة والمزدوجة</h3>

<p>بايثون لا تملك حماية صارمة حقيقية مثل بعض اللغات، لكنها تستخدم اصطلاحات (conventions) واضحة: خاصية تبدأ بشرطة سفلية واحدة <code>_balance</code> تعني "داخلية، لا تصل إليها من خارج الصنف رغم إمكانية ذلك تقنياً" — تحذير احترام لا حماية إجبارية. الشرطتان السفليتان <code>__balance</code> تُفعّلان تشويهاً حقيقياً لاسم الخاصية (name mangling) يجعل الوصول المباشر من خارج الصنف أصعب فعلياً.</p>

<h3>Property: التحقّق عند القراءة والكتابة</h3>

<p>الأداة الأنيقة لـ Encapsulation في بايثون هي <code>@property</code>: تسمح بتعريف method تتصرّف وكأنها خاصية عادية عند القراءة (<code>account.balance</code> بلا أقواس)، بينما هي فعلياً دالة تتحكّم في القيمة المُرجَعة. يمكن إقرانها بـ <code>@balance.setter</code> لتعريف دالة تتحقّق من القيمة قبل قبول أي تعديل عليها.</p>

<h3>لماذا هذا مهم عملياً؟</h3>

<p>تخيّل صنف حساب بنكي: بلا Encapsulation، أي كود يستطيع كتابة <code>account.balance = -1000000</code> مباشرة، منتجاً رصيداً سالباً مستحيلاً منطقياً. مع <code>@property</code> وsetter يتحقّق من القيمة، أي محاولة تعيين رصيد سالب تُرفَض فوراً برسالة واضحة (باستخدام <code>raise</code> من درس سابق)، بدل السماح ببيانات فاسدة تنتشر بصمت.</p>

<h3>أخطاء شائعة</h3>

<p>الاعتماد الكامل على الشرطة السفلية الواحدة كأنها حماية حقيقية — إنها اصطلاح فقط، ولا شيء يمنع الوصول المباشر تقنياً. للحماية الفعلية عند التحقّق ضروري، استخدم <code>@property</code> مع setter يتحقّق فعلياً.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>Encapsulation يحمي بيانات الكائن من تعديل مباشر غير مُتحكَّم به</li>
    <li>شرطة سفلية واحدة <code>_name</code>: اصطلاح "داخلي" غير مُلزَم تقنياً</li>
    <li>شرطتان سفليتان <code>__name</code>: تشويه حقيقي لاسم الخاصية</li>
    <li><code>@property</code> و<code>@x.setter</code> يسمحان بالتحقّق الفعلي عند القراءة والكتابة</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>عرّف صنف <code>BankAccount</code> بخاصية داخلية <code>_balance</code>، وproperty باسم <code>balance</code> للقراءة، وsetter يرفض أي قيمة سالبة بـ <code>raise ValueError</code>. اختبر تعيين قيمة صالحة وأخرى سالبة.</p>
`,
        en: `<p>Encapsulation protects an object's internal data from uncontrolled direct edits. A single underscore _name is a "internal use" convention, not real protection. @property and @x.setter give real control: the setter can validate a value with raise before accepting it, rejecting invalid states like a negative balance.</p>`
    },
    code: `<span class="kw">class</span> BankAccount:
    <span class="kw">def</span> __init__(self, owner, balance):
        self.owner = owner
        self._balance = balance   <span class="cm"># شرطة واحدة: اصطلاح "داخلي"</span>

    <span class="cm"># property: تُقرأ كخاصية عادية بلا أقواس</span>
    <span class="fn">@property</span>
    <span class="kw">def</span> balance(self):
        <span class="kw">return</span> self._balance

    <span class="cm"># setter: يتحقّق قبل قبول أي تعديل</span>
    <span class="fn">@balance.setter</span>
    <span class="kw">def</span> balance(self, new_value):
        <span class="kw">if</span> new_value < 0:
            <span class="kw">raise</span> <span class="fn">ValueError</span>(<span class="st">"Balance cannot be negative"</span>)
        self._balance = new_value


<span class="kw">account</span> = BankAccount(<span class="st">"Sarah"</span>, 1000)

<span class="fn">print</span>(account.balance)     <span class="cm"># 1000 — تُقرأ كخاصية عادية</span>

account.balance = 1500          <span class="cm"># تعديل صالح — يمرّ عبر setter بأمان</span>
<span class="fn">print</span>(account.balance)     <span class="cm"># 1500</span>

<span class="kw">try</span>:
    account.balance = -500      <span class="cm"># محاولة غير منطقية</span>
<span class="kw">except</span> <span class="fn">ValueError</span> <span class="kw">as</span> e:
    <span class="fn">print</span>(<span class="st">f"Rejected: {e}"</span>)

<span class="fn">print</span>(account.balance)     <span class="cm"># لا يزال 1500 — لم يتغيّر</span>`,
    quiz: {
        q: {
            ar: "لماذا لا تُعتبر self._balance (شرطة واحدة) حماية حقيقية لبيانات الكائن؟",
            en: "Why isn't self._balance (single underscore) real protection for object data?"
        },
        options: {
            ar: [
                "لأنها اصطلاح فقط يُفهم بين المبرمجين، ولا يمنع الوصول المباشر تقنياً من خارج الصنف",
                "لأنها تعمل فقط داخل __init__",
                "لأن بايثون تمنعها من الأساس",
                "لا فرق بينها وبين @property إطلاقاً"
            ],
            en: [
                "It's just a convention understood between programmers, and doesn't technically prevent direct access from outside the class",
                "It only works inside __init__",
                "Python forbids it outright",
                "There's no difference at all from @property"
            ]
        },
        correct: 0,
        explanation: {
            ar: "الشرطة السفلية الواحدة رسالة اصطلاحية بين المبرمجين تقول 'لا تصل لهذا مباشرة'، لكن بايثون لا تفرضها تقنياً — account._balance = -500 سيعمل فعلياً بلا أي منع. الحماية الفعلية تحتاج @property مع setter يتحقّق صراحة.",
            en: "A single underscore is a conventional message between programmers saying 'don't access this directly', but Python doesn't technically enforce it — account._balance = -500 would actually work with no prevention at all. Real protection needs @property with a setter that explicitly validates."
        }
    }
},

/* ---------- الدرس 37 ---------- */
{
    title: { ar: "Magic Methods: تخصيص سلوك الكائنات", en: "Magic methods: customizing object behavior" },
    body: {
        ar: `
<p>جرّب طباعة كائن من أصناف الدروس السابقة مباشرة: <code>print(book)</code> — ستحصل على شيء غير مفيد مثل <code>&lt;__main__.Book object at 0x...&gt;</code>. لماذا لا يطبع بيانات الكتاب الفعلية؟ لأن بايثون لا "تعرف" كيف تريد تمثيل كائنك كنصّ، إلا إن أخبرتها بنفسك عبر <strong>Magic Methods</strong> — دوال خاصة تبدأ وتنتهي بشرطتين سفليتين، تُستدعى تلقائياً في مواقف محدّدة.</p>

<h3>__str__: التمثيل النصّي المقروء</h3>

<p>تعريف <code>__str__(self)</code> داخل الصنف يُخبر بايثون كيف تُحوّل الكائن لنصّ عند <code>print()</code> أو <code>str()</code>: <code>def __str__(self): return f"{self.title} by {self.author}"</code>. الآن <code>print(book)</code> يطبع هذا النصّ الواضح بدل العنوان التقني الافتراضي.</p>

<h3>__len__: تخصيص len()</h3>

<p>إن كان صنفك يمثّل مجموعة من شيء ما (كصنف مكتبة يحتوي كتباً)، تعريف <code>__len__(self)</code> يجعل <code>len(library)</code> يعمل مباشرة على كائنك، مُرجعاً عدد الكتب مثلاً — بدل الحاجة لدالة منفصلة كـ <code>library.count_books()</code>.</p>

<h3>__eq__: تخصيص المقارنة بـ ==</h3>

<p>افتراضياً، <code>==</code> بين كائنين من نفس الصنف يقارن هوية الذاكرة (هل هما نفس الكائن بالضبط؟)، وليس تساوي محتواهما. تعريف <code>__eq__(self, other)</code> يسمح بتخصيص معنى المساواة: مثلاً، كتابان متساويان إن تطابق عنوانهما ومؤلفهما، حتى لو كانا كائنين مختلفين تماماً في الذاكرة.</p>

<h3>لماذا Magic Methods قوية؟</h3>

<p>تسمح لكائناتك بالتصرّف بشكل طبيعي مع دوال بايثون المدمجة (<code>print</code>, <code>len</code>, <code>==</code>, وغيرها الكثير) بدل اختراع methods مخصّصة بأسماء مختلفة في كل صنف. هذا يجعل كودك أكثر اتساقاً وقابلية للتنبؤ لأي شخص يقرأه.</p>

<h3>أخطاء شائعة</h3>

<p>نسيان أن <code>__str__</code> يجب أن تُرجع نصّاً (<code>str</code>) دائماً — إرجاع نوع آخر يرمي <code>TypeError</code>. والخلط بين <code>__str__</code> (للعرض البشري المقروء) و<code>__repr__</code> (تمثيل تقني أدق يُستخدم غالباً في التصحيح Debugging) — إن عرَّفت واحدة فقط ابدأ بـ <code>__str__</code>.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>Magic Methods تبدأ وتنتهي بشرطتين سفليتين، وتُستدعى تلقائياً في مواقف محدّدة</li>
    <li><code>__str__</code> يخصّص تمثيل الكائن كنصّ عند <code>print()</code></li>
    <li><code>__len__</code> يخصّص سلوك <code>len()</code> على كائنك</li>
    <li><code>__eq__</code> يخصّص معنى المقارنة بـ <code>==</code> بين كائنين</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>أضف للصنف <code>Book</code> دالة <code>__str__</code> تُرجع تمثيلاً واضحاً، ودالة <code>__eq__</code> تعتبر كتابين متساويين إن تطابق العنوان فقط. اختبر <code>print()</code> و<code>==</code> على كائنات حقيقية.</p>
`,
        en: `<p>Magic methods (starting/ending with double underscores) let your class integrate with Python's built-in functions. __str__ customizes print(object), __len__ customizes len(object), and __eq__ customizes what == means between two objects of your class — comparing content instead of memory identity.</p>`
    },
    code: `<span class="kw">class</span> Book:
    <span class="kw">def</span> __init__(self, title, author):
        self.title = title
        self.author = author

    <span class="cm"># __str__: كيف يُطبع الكائن</span>
    <span class="kw">def</span> __str__(self):
        <span class="kw">return</span> <span class="st">f"{self.title} by {self.author}"</span>

    <span class="cm"># __eq__: كيف يُقارَن كائنان بـ ==</span>
    <span class="kw">def</span> __eq__(self, other):
        <span class="kw">return</span> self.title == other.title <span class="kw">and</span> self.author == other.author


<span class="kw">class</span> Library:
    <span class="kw">def</span> __init__(self):
        self.books = []

    <span class="kw">def</span> add(self, book):
        self.books.append(book)

    <span class="cm"># __len__: كيف يعمل len() على الكائن</span>
    <span class="kw">def</span> __len__(self):
        <span class="kw">return</span> <span class="fn">len</span>(self.books)


<span class="kw">book1</span> = Book(<span class="st">"Python Basics"</span>, <span class="st">"Sarah Ahmed"</span>)
<span class="kw">book2</span> = Book(<span class="st">"Python Basics"</span>, <span class="st">"Sarah Ahmed"</span>)

<span class="fn">print</span>(book1)              <span class="cm"># Python Basics by Sarah Ahmed — بفضل __str__</span>
<span class="fn">print</span>(book1 == book2)    <span class="cm"># True — نفس المحتوى، بفضل __eq__</span>

<span class="kw">library</span> = Library()
library.add(book1)
library.add(book2)
<span class="fn">print</span>(<span class="fn">len</span>(library))     <span class="cm"># 2 — بفضل __len__</span>`,
    quiz: {
        q: {
            ar: "بدون تعريف __str__، ماذا يحدث عند طباعة كائن بـ print(book)؟",
            en: "Without defining __str__, what happens when you print an object with print(book)?"
        },
        options: {
            ar: [
                "يرمي بايثون خطأً فورياً",
                "يطبع تمثيلاً تقنياً غير مفيد مثل عنوان الكائن في الذاكرة، بدل بياناته الفعلية",
                "يطبع كل خصائص الكائن تلقائياً بصيغة قاموس",
                "لا يمكن طباعة كائن بايثون إطلاقاً بدون __str__"
            ],
            en: [
                "Python raises an immediate error",
                "It prints an unhelpful technical representation, like the object's memory address, instead of its actual data",
                "It automatically prints all the object's attributes as a dict",
                "A Python object can never be printed at all without __str__"
            ]
        },
        correct: 1,
        explanation: {
            ar: "بلا __str__ مخصّصة، بايثون تستخدم التمثيل الافتراضي مثل <__main__.Book object at 0x...> — تقني وغير مفيد. تعريف __str__ يُخبر بايثون كيف تحوّل الكائن لنصّ واضح مفهوم بشرياً عند الطباعة.",
            en: "Without a custom __str__, Python uses the default representation like <__main__.Book object at 0x...> — technical and unhelpful. Defining __str__ tells Python how to convert the object into a clear, human-readable string when printed."
        }
    }
},

/* ---------- الدرس 38 — مشروع ---------- */
{
    title: { ar: "مشروع 6: نظام مكتبة", en: "Project 6: Library system" },
    body: {
        ar: `
<p>مشروع هذا المستوى يجمع كل ما تعلمته في OOP: الأصناف والكائنات، methods، الوراثة، Encapsulation، وMagic Methods. ستبني نظام مكتبة بسيط بأصناف حقيقية مترابطة، بدل قواميس وقوائم منفصلة عن بعضها كما فعلت في مشاريع سابقة.</p>

<h3>التصميم: أصناف متعاونة</h3>

<p>ثلاثة أصناف رئيسية: <code>Book</code> (كتاب فردي بعنوان ومؤلف وحالة استعارة)، <code>Library</code> (تحتوي قائمة كتب، وmethods للإضافة والاستعارة والإرجاع)، واستفدنا من الوراثة لإنشاء <code>EBook</code> يرث من <code>Book</code> ويضيف حجم الملف. هذا التصميم — أصناف صغيرة، كل منها مسؤول عن شيء واحد واضح — أساس التصميم الجيد في OOP.</p>

<h3>Encapsulation في الاستعارة</h3>

<p>حالة الاستعارة (<code>is_borrowed</code>) محمية داخل الصنف: لا يُعدِّلها كود خارجي مباشرة، بل عبر methods <code>borrow()</code> و<code>return_book()</code> التي تتحقّق من الحالة الحالية أولاً — لا يمكن استعارة كتاب مُستعار بالفعل، ولا إرجاع كتاب غير مُستعار أصلاً. هذا بالضبط جوهر Encapsulation: منع حالات غير منطقية عبر فرض المرور بمنطق تحقّق موحّد.</p>

<h3>Magic Methods لتجربة أنظف</h3>

<p><code>__str__</code> على <code>Book</code> يجعل طباعة أي كتاب تعرض بياناته مباشرة بدل عنوان تقني، و<code>__len__</code> على <code>Library</code> يجعل <code>len(library)</code> يعمل طبيعياً لمعرفة عدد الكتب — تكامل أنيق مع دوال بايثون المدمجة بدل اختراع methods بأسماء مختلفة.</p>

<h3>تحديات للتوسيع</h3>

<ul>
    <li>أضف صنف <code>Member</code> يمثّل مستعير الكتاب، واربطه بـ <code>borrow()</code></li>
    <li>أضف method <code>available_books()</code> تُرجع فقط الكتب غير المُستعارة حالياً</li>
    <li>احفظ حالة المكتبة في ملف JSON عند الإغلاق (بما تعلمته في المستوى الخامس)</li>
    <li>أضف <code>__eq__</code> على <code>Book</code> يعتبر كتابين متطابقين إن تطابق عنوانهما</li>
</ul>

<h3>ماذا أنجزت في هذا المستوى؟</h3>

<ul>
    <li>جمعت البيانات والسلوك معاً في أصناف بدل قواميس منفصلة عن منطقها</li>
    <li>عرّفت methods تعمل على بيانات كل كائن عبر self</li>
    <li>بنيت تسلسلاً هرمياً بالوراثة، مع Override لتخصيص سلوك الابن</li>
    <li>حميت بيانات الكائنات من تعديل مباشر غير منطقي بـ Encapsulation</li>
    <li>خصّصت سلوك كائناتك مع دوال بايثون المدمجة عبر Magic Methods</li>
    <li>وبنيت نظاماً حقيقياً بأصناف متعاونة تمثّل مشكلة واقعية بوضوح</li>
</ul>

<p>في المستوى السابع والأخير سنتعلّم أدوات الاحتراف: تنظيم الكود بوحدات (modules)، تثبيت مكتبات خارجية بـ pip، Decorators، Generators، ومعايير كتابة كود بايثون نظيف (PEP 8) — لتصبح جاهزاً فعلياً للمشاريع الحقيقية.</p>
`,
        en: `<p>This capstone combines classes, methods, inheritance, encapsulation, and magic methods into a library system: Book and Library classes collaborate, EBook inherits from Book, borrow()/return_book() enforce valid state transitions, and __str__/__len__ integrate cleanly with Python's built-ins.</p>`
    },
    code: `<span class="cm"># ============================================</span>
<span class="cm"># نظام مكتبة</span>
<span class="cm"># ============================================</span>

<span class="kw">class</span> Book:
    <span class="kw">def</span> __init__(self, title, author):
        self.title = title
        self.author = author
        self._is_borrowed = <span class="kw">False</span>

    <span class="kw">def</span> borrow(self):
        <span class="kw">if</span> self._is_borrowed:
            <span class="kw">raise</span> <span class="fn">ValueError</span>(<span class="st">f"{self.title} is already borrowed"</span>)
        self._is_borrowed = <span class="kw">True</span>

    <span class="kw">def</span> return_book(self):
        <span class="kw">if</span> <span class="kw">not</span> self._is_borrowed:
            <span class="kw">raise</span> <span class="fn">ValueError</span>(<span class="st">f"{self.title} was not borrowed"</span>)
        self._is_borrowed = <span class="kw">False</span>

    <span class="kw">def</span> __str__(self):
        <span class="kw">status</span> = <span class="st">"borrowed"</span> <span class="kw">if</span> self._is_borrowed <span class="kw">else</span> <span class="st">"available"</span>
        <span class="kw">return</span> <span class="st">f"{self.title} by {self.author} ({status})"</span>


<span class="cm"># EBook يرث من Book ويضيف خاصية خاصة به</span>
<span class="kw">class</span> EBook(Book):
    <span class="kw">def</span> __init__(self, title, author, file_size_mb):
        <span class="fn">super</span>().__init__(title, author)
        self.file_size_mb = file_size_mb


<span class="kw">class</span> Library:
    <span class="kw">def</span> __init__(self):
        self.books = []

    <span class="kw">def</span> add(self, book):
        self.books.append(book)

    <span class="kw">def</span> __len__(self):
        <span class="kw">return</span> <span class="fn">len</span>(self.books)


<span class="kw">library</span> = Library()
library.add(Book(<span class="st">"Python Basics"</span>, <span class="st">"Sarah Ahmed"</span>))
library.add(EBook(<span class="st">"Data Science"</span>, <span class="st">"Ahmed Ali"</span>, 12))

<span class="fn">print</span>(<span class="st">f"Library has {len(library)} books"</span>)

<span class="kw">for</span> book <span class="kw">in</span> library.books:
    <span class="fn">print</span>(book)

library.books[0].borrow()
<span class="fn">print</span>(library.books[0])

<span class="kw">try</span>:
    library.books[0].borrow()   <span class="cm"># محاولة استعارة كتاب مُستعار بالفعل</span>
<span class="kw">except</span> <span class="fn">ValueError</span> <span class="kw">as</span> e:
    <span class="fn">print</span>(<span class="st">f"Error: {e}"</span>)`,
    quiz: {
        q: {
            ar: "لماذا ترمي borrow() خطأً بدل السماح باستعارة كتاب مُستعار بالفعل؟",
            en: "Why does borrow() raise an error instead of allowing a book that's already borrowed to be borrowed again?"
        },
        options: {
            ar: [
                "خطأ في التصميم، يجب أن تسمح دائماً بالاستعارة",
                "لأن هذا Encapsulation فعلي: منع حالة غير منطقية (كتاب مُستعار مرتين) عبر فرض التحقّق داخل الصنف نفسه",
                "لأن بايثون تمنع استدعاء method مرتين تلقائياً",
                "لا علاقة لهذا بـ Encapsulation إطلاقاً"
            ],
            en: [
                "A design mistake — it should always allow borrowing",
                "Because this is real encapsulation: preventing an illogical state (a book borrowed twice) by enforcing the check inside the class itself",
                "Because Python automatically prevents calling a method twice",
                "This has nothing to do with encapsulation at all"
            ]
        },
        correct: 1,
        explanation: {
            ar: "بدون هذا التحقّق، أي كود خارجي يستطيع تعيين _is_borrowed كما يشاء دون منطق، فينتج حالات مستحيلة منطقياً. فرض المرور عبر borrow() التي تتحقّق أولاً هو بالضبط جوهر Encapsulation: حماية اتساق بيانات الكائن الداخلية.",
            en: "Without this check, any external code could set _is_borrowed however it wants with no logic, producing logically impossible states. Forcing access through borrow(), which checks first, is exactly the point of encapsulation: protecting the object's internal data consistency."
        }
    }
}
,

/* ---------- الدرس 39 ---------- */
{
    title: { ar: "الوحدات (Modules) والاستيراد", en: "Modules and import" },
    body: {
        ar: `
<p>كل مشروع كتبته حتى الآن كان في ملف واحد. لكن مشروعاً حقيقياً بآلاف الأسطر لا يمكن أن يعيش في ملف واحد بشكل معقول — يصبح فوضوياً، وصعب التنقّل فيه، وصعب إعادة استخدام أي جزء منه في مشروع آخر. <strong>الوحدة (Module)</strong> هي ببساطة ملف بايثون آخر يحتوي دوالاً أو أصنافاً يمكن <strong>استيرادها</strong> واستخدامها من ملفك الحالي.</p>

<h3>استخدمت الوحدات بالفعل</h3>

<p>تذكّر <code>import random</code> و<code>import json</code> و<code>import csv</code> من دروس سابقة — هذه وحدات مدمجة في بايثون (Standard Library) توفّر دوالاً جاهزة لم تكن مضطراً لكتابتها بنفسك. نفس المبدأ ينطبق على وحداتك الخاصة.</p>

<h3>إنشاء واستيراد وحدة خاصة</h3>

<p>أي ملف <code>.py</code> هو وحدة بحدّ ذاته. لو كتبت دوالاً في ملف <code>math_tools.py</code>، تستطيع استيرادها من ملف آخر في نفس المجلد بـ <code>import math_tools</code> ثم استدعاء <code>math_tools.square(5)</code>، أو باستيراد اسم محدّد مباشرة: <code>from math_tools import square</code> ثم استدعائها مباشرة بلا بادئة: <code>square(5)</code>.</p>

<h3>__name__ == "__main__"</h3>

<p>نمط شائع جداً تراه في كل مشروع بايثون احترافي: <code>if __name__ == "__main__":</code> في نهاية الملف. هذا الشرط يكون صحيحاً فقط عند تشغيل الملف <strong>مباشرة</strong>، لكنه خاطئ عند استيراده كوحدة من ملف آخر. يسمح هذا بوضع كود اختباري أو تجريبي في الملف نفسه، يعمل عند تشغيله وحده، لكن لا يتداخل مع الاستيراد من ملفات أخرى.</p>

<h3>لماذا نقسّم لوحدات متعددة؟</h3>

<p>ثلاثة أسباب: <strong>التنظيم</strong> (كل ملف مسؤول عن جزء واضح من المنطق)، <strong>إعادة الاستخدام</strong> (نفس الوحدة تُستورَد في عدة مشاريع دون نسخ ولصق)، و<strong>سهولة الصيانة</strong> (تعديل جزء واحد لا يتطلّب فتح ملف ضخم بآلاف الأسطر للبحث فيه).</p>

<h3>أخطاء شائعة</h3>

<p>محاولة استيراد وحدة من مجلد مختلف بدون فهم مسارات بايثون (نادراً ما تحتاج هذا كمبتدئ). وتسمية ملفك بنفس اسم وحدة مدمجة (مثل <code>random.py</code>) — هذا يُربك بايثون ويجعله يستورد ملفك بدل الوحدة الأصلية بالخطأ.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>الوحدة ملف <code>.py</code> يحتوي دوالاً/أصنافاً قابلة للاستيراد من ملفات أخرى</li>
    <li><code>import module_name</code> يستورد الوحدة كاملة؛ <code>from module import name</code> يستورد شيئاً محدداً</li>
    <li><code>if __name__ == "__main__":</code> يُنفَّذ فقط عند تشغيل الملف مباشرة، لا عند استيراده</li>
    <li>تقسيم الكود لوحدات يحسّن التنظيم وإعادة الاستخدام وسهولة الصيانة</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>أنشئ ملفاً باسم <code>string_utils.py</code> فيه دالة <code>reverse_words(sentence)</code> تعكس ترتيب الكلمات في جملة. استوردها من ملف آخر واستخدمها، مع إضافة <code>if __name__ == "__main__":</code> يحتوي كود اختبار سريع في الملف الأصلي نفسه.</p>
`,
        en: `<p>A module is just a .py file containing functions/classes that other files can import: import module_name imports the whole module; from module import name imports something specific. if __name__ == "__main__": runs only when the file is executed directly, not when imported elsewhere.</p>`
    },
    code: `<span class="cm"># وحدات مدمجة استخدمتها من قبل</span>
<span class="kw">import</span> random
<span class="kw">import</span> json


<span class="cm"># --- في ملف منفصل باسم string_utils.py ---</span>
<span class="cm"># def reverse_words(sentence):</span>
<span class="cm">#     words = sentence.split()</span>
<span class="cm">#     return " ".join(reversed(words))</span>
<span class="cm">#</span>
<span class="cm"># if __name__ == "__main__":</span>
<span class="cm">#     # هذا يُنفَّذ فقط عند تشغيل الملف مباشرة، لا عند استيراده</span>
<span class="cm">#     print(reverse_words("Hello World"))</span>


<span class="cm"># --- في ملف آخر يستورد الوحدة أعلاه ---</span>
<span class="cm"># import string_utils</span>
<span class="cm"># print(string_utils.reverse_words("Python is fun"))</span>

<span class="cm"># أو استيراد اسم محدّد مباشرة</span>
<span class="cm"># from string_utils import reverse_words</span>
<span class="cm"># print(reverse_words("Python is fun"))   ← بلا بادئة الوحدة</span>


<span class="cm"># مثال فعلي بوحدة مدمجة</span>
<span class="kw">secret_number</span> = random.randint(1, 100)
<span class="fn">print</span>(<span class="st">f"Random number: {secret_number}"</span>)`,
    quiz: {
        q: {
            ar: "متى يكون شرط if __name__ == \"__main__\": صحيحاً؟",
            en: "When is the condition if __name__ == \"__main__\": true?"
        },
        options: {
            ar: [
                "دائماً صحيح، بغض النظر عن طريقة تشغيل الملف",
                "فقط عندما يُشغَّل الملف مباشرة، وليس عند استيراده كوحدة من ملف آخر",
                "فقط عند استيراد الملف من ملف آخر",
                "لا علاقة له بطريقة التشغيل إطلاقاً"
            ],
            en: [
                "Always true, regardless of how the file is run",
                "Only when the file is run directly, not when it's imported as a module from another file",
                "Only when the file is imported from another file",
                "It has nothing to do with how the file is run"
            ]
        },
        correct: 1,
        explanation: {
            ar: "بايثون تعيّن __name__ إلى '__main__' فقط عند تشغيل الملف مباشرة (python file.py). عند استيراده من ملف آخر، تكون __name__ مساوية لاسم الوحدة نفسها، فيصبح الشرط خاطئاً ولا يُنفَّذ الكود بداخله.",
            en: "Python sets __name__ to '__main__' only when the file is run directly (python file.py). When imported from another file, __name__ equals the module's own name instead, so the condition is false and the code inside doesn't run."
        }
    }
},

/* ---------- الدرس 40 ---------- */
{
    title: { ar: "pip: تثبيت المكتبات الخارجية", en: "pip: installing external packages" },
    body: {
        ar: `
<p>الوحدات المدمجة (كـ <code>random</code> و<code>json</code>) رائعة، لكنها محدودة بما يأتي مع بايثون افتراضياً. المجتمع العالمي لمبرمجي بايثون نشر <strong>مئات آلاف المكتبات الجاهزة</strong> لكل غرض تقريباً: تحليل بيانات (<code>pandas</code>)، بناء مواقع (<code>Django</code>, <code>Flask</code>)، ذكاء اصطناعي (<code>tensorflow</code>)، وغيرها. <strong>pip</strong> هو الأداة التي تُثبّت هذه المكتبات على جهازك من الطرفية مباشرة.</p>

<h3>تثبيت مكتبة بـ pip</h3>

<p>من الطرفية (وليس داخل كود بايثون): <code>pip install requests</code> يُثبّت مكتبة <code>requests</code> الشهيرة للتعامل مع الويب. بعد التثبيت، تستوردها في كودك بنفس طريقة أي وحدة أخرى: <code>import requests</code>.</p>

<h3>requirements.txt: توثيق المكتبات المطلوبة</h3>

<p>عند مشاركة مشروع مع آخرين، لا تُرسل المكتبات المُثبَّتة نفسها — بل ملف نصّي باسم <code>requirements.txt</code> يسرد أسماءها: <code>requests\\npandas\\nflask</code>. أي شخص يستلم مشروعك يشغّل أمراً واحداً: <code>pip install -r requirements.txt</code> فيُثبَّت كل شيء دفعة واحدة تلقائياً.</p>

<h3>البيئات الافتراضية (Virtual Environments)</h3>

<p>مشاريع مختلفة قد تحتاج نسخاً مختلفة من نفس المكتبة. <strong>البيئة الافتراضية</strong> (venv) تعزل مكتبات كل مشروع عن الآخر، فلا يتعارض تثبيت مكتبة لمشروع مع مشروع آخر على نفس الجهاز. تُنشأ بأمر <code>python -m venv myenv</code>، وتُفعَّل قبل تثبيت أي مكتبة داخل مشروع محدّد — ممارسة احترافية أساسية رغم أنها ليست ضرورية لتجاربك التعليمية الأولى.</p>

<h3>لماذا هذا مهم؟</h3>

<p>القدرة على استخدام عمل آلاف المبرمجين الآخرين جاهزاً توفّر أسابيع أو أشهراً من العمل. بدل إعادة اختراع كل شيء من الصفر، تُثبّت المكتبة المناسبة وتبني فوق عملها مباشرة — هذا بالضبط ما يجعل بايثون قوية جداً في العالم الحقيقي.</p>

<h3>أخطاء شائعة</h3>

<p>كتابة <code>pip install</code> داخل كود بايثون نفسه بدل الطرفية — <code>pip</code> أمر طرفية، لا دالة بايثون. ونسيان تحديث <code>requirements.txt</code> بعد تثبيت مكتبة جديدة، فيفشل تثبيت المشروع لاحقاً عند شخص آخر بسبب مكتبة ناقصة من القائمة.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li><code>pip install package_name</code> يُثبّت مكتبة خارجية من الطرفية</li>
    <li><code>requirements.txt</code> يوثّق كل المكتبات المطلوبة لمشروعك بمكان واحد</li>
    <li><code>pip install -r requirements.txt</code> يُثبّت كل شيء دفعة واحدة</li>
    <li>البيئات الافتراضية تعزل مكتبات كل مشروع عن مشاريع أخرى على نفس الجهاز</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>افتح الطرفية وثبّت مكتبة <code>requests</code> بـ <code>pip install requests</code>. أنشئ ملف <code>requirements.txt</code> يحتوي اسمها، ثم اكتب برنامجاً صغيراً يستوردها ويطبع <code>requests.__version__</code> للتأكد من التثبيت.</p>
`,
        en: `<p>pip install package_name (run in the terminal, not inside Python code) installs external libraries beyond Python's built-ins. requirements.txt lists a project's dependencies so pip install -r requirements.txt can install them all at once. Virtual environments isolate each project's packages from others on the same machine.</p>`
    },
    code: `<span class="cm"># هذه الأوامر تُكتب في الطرفية، وليست كود بايثون!</span>

<span class="cm"># 1) تثبيت مكتبة خارجية</span>
pip install requests

<span class="cm"># 2) إنشاء بيئة افتراضية معزولة (اختياري لكن مُوصى به)</span>
python -m venv myenv

<span class="cm"># 3) تفعيل البيئة الافتراضية</span>
<span class="cm"># على ويندوز:</span>
myenv\\Scripts\\activate
<span class="cm"># على macOS/Linux:</span>
<span class="cm"># source myenv/bin/activate</span>

<span class="cm"># 4) تثبيت كل مكتبات المشروع من ملف واحد</span>
pip install -r requirements.txt


<span class="cm"># ============================================</span>
<span class="cm"># الكود التالي هو بايثون فعلي، بعد التثبيت</span>
<span class="cm"># ============================================</span>
<span class="kw">import</span> requests

<span class="fn">print</span>(<span class="st">f"requests version: {requests.__version__}"</span>)

<span class="cm"># محتوى requirements.txt نموذجي:</span>
<span class="cm"># requests</span>
<span class="cm"># pandas</span>
<span class="cm"># flask</span>`,
    quiz: {
        q: {
            ar: "ما وظيفة ملف requirements.txt في مشروع بايثون؟",
            en: "What is the purpose of a requirements.txt file in a Python project?"
        },
        options: {
            ar: [
                "يحتوي كود بايثون قابلاً للتنفيذ مباشرة",
                "يسرد أسماء المكتبات الخارجية المطلوبة، ليثبّتها أي شخص آخر بأمر واحد",
                "يُشغَّل تلقائياً عند فتح المشروع",
                "يحتوي كلمات مرور المشروع فقط"
            ],
            en: [
                "It contains directly executable Python code",
                "It lists the external libraries a project needs, so anyone else can install them with a single command",
                "It runs automatically whenever the project is opened",
                "It only contains the project's passwords"
            ]
        },
        correct: 1,
        explanation: {
            ar: "requirements.txt ملف نصّي بسيط يسرد أسماء المكتبات (وأحياناً إصداراتها)، فيستطيع أي شخص يستلم المشروع تثبيت كل شيء دفعة واحدة بأمر pip install -r requirements.txt بدل البحث يدوياً عن كل مكتبة مطلوبة.",
            en: "requirements.txt is a simple text file listing library names (and sometimes versions), so anyone who receives the project can install everything at once with pip install -r requirements.txt instead of manually hunting down each required library."
        }
    }
},

/* ---------- الدرس 41 ---------- */
{
    title: { ar: "args وkwargs: معاملات مرنة", en: "*args and **kwargs: flexible parameters" },
    body: {
        ar: `
<p>كل دالة كتبتها حتى الآن كان لها عدد معاملات ثابت ومحدّد سلفاً. لكن ماذا لو أردت دالة <code>total(*)</code> تجمع أي عدد من الأرقام، اثنين أو عشرة؟ كتابة معامل منفصل لكل حالة مستحيلة عملياً. بايثون توفّر أداتين لهذا بالضبط: <code>*args</code> و<code>**kwargs</code>، تسمحان لدالة باستقبال عدد <strong>غير محدّد</strong> من الوسائط.</p>

<h3>*args: عدد غير محدّد من الوسائط الموضعية</h3>

<p>وضع نجمة قبل اسم معامل، مثل <code>def total(*numbers):</code>، تجمع كل الوسائط الموضعية الممرَّرة في Tuple واحد باسم <code>numbers</code>. يمكنك استدعاء <code>total(1, 2)</code> أو <code>total(1, 2, 3, 4, 5)</code> بنفس الدالة، دون تعريف عدد ثابت من المعاملات مسبقاً.</p>

<h3>**kwargs: عدد غير محدّد من الوسائط المسمّاة</h3>

<p>نجمتان قبل اسم معامل، مثل <code>def describe(**info):</code>، تجمع كل الوسائط المسمّاة الممرَّرة في قاموس واحد باسم <code>info</code>. استدعاء <code>describe(name="Sarah", age=22)</code> يجعل <code>info</code> يساوي <code>{"name": "Sarah", "age": 22}</code> — مفيدة جداً عندما لا تعرف مسبقاً أي معلومات إضافية قد يريد المستخدم تمريرها.</p>

<h3>الترتيب الصحيح عند الجمع بينها</h3>

<p>يمكن الجمع بين معاملات عادية، <code>*args</code>، و<code>**kwargs</code> في نفس الدالة، لكن بترتيب إلزامي: المعاملات العادية أولاً، ثم <code>*args</code>، ثم <code>**kwargs</code> أخيراً دائماً: <code>def f(a, b, *args, **kwargs):</code>.</p>

<h3>لماذا هذا مهم للدرس القادم؟</h3>

<p>هذا الدرس أساسي لفهم <strong>Decorators</strong> في الدرس التالي — أي decorator عام يحتاج تمرير أي دالة بأي عدد ونوع معاملات، وهذا مستحيل بدون <code>*args</code> و<code>**kwargs</code> لاستقبال "كل شيء ممكن" دون معرفته مسبقاً.</p>

<h3>أخطاء شائعة</h3>

<p>الخلط بين ترتيب <code>*args</code> و<code>**kwargs</code> عند التعريف — <code>**kwargs</code> يجب أن يكون دائماً الأخير. ونسيان أن <code>args</code> داخل الدالة هو Tuple عادي، فتحتاج التكرار عليه أو استخدام دوال Tuple المعتادة، وليس فهرسة كأنه معامل واحد.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li><code>*args</code> يجمع الوسائط الموضعية غير المحدودة في Tuple</li>
    <li><code>**kwargs</code> يجمع الوسائط المسمّاة غير المحدودة في قاموس</li>
    <li>الترتيب الإلزامي: معاملات عادية، ثم <code>*args</code>، ثم <code>**kwargs</code></li>
    <li>أساس فهم Decorators، التي تحتاج تمرير أي دالة بأي معاملات</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>اكتب دالة <code>total(*numbers)</code> تُرجع مجموع أي عدد من الأرقام الممرَّرة، ودالة <code>print_profile(**info)</code> تطبع كل زوج مفتاح وقيمة ممرَّر إليها. اختبر الاثنتين بعدد مختلف من الوسائط في كل مرة.</p>
`,
        en: `<p>*args collects any number of positional arguments into a tuple; **kwargs collects any number of keyword arguments into a dict. Combine them as def f(a, b, *args, **kwargs) — regular parameters first, then *args, then **kwargs. This is essential for writing generic decorators next.</p>`
    },
    code: `<span class="cm"># *args: عدد غير محدّد من الوسائط الموضعية</span>
<span class="kw">def</span> total(*numbers):
    <span class="fn">print</span>(<span class="fn">type</span>(numbers))   <span class="cm"># &lt;class 'tuple'&gt;</span>
    <span class="kw">return</span> <span class="fn">sum</span>(numbers)

<span class="fn">print</span>(total(1, 2))            <span class="cm"># 3</span>
<span class="fn">print</span>(total(1, 2, 3, 4, 5))   <span class="cm"># 15 — نفس الدالة، عدد مختلف</span>


<span class="cm"># **kwargs: عدد غير محدّد من الوسائط المسمّاة</span>
<span class="kw">def</span> print_profile(**info):
    <span class="fn">print</span>(<span class="fn">type</span>(info))     <span class="cm"># &lt;class 'dict'&gt;</span>
    <span class="kw">for</span> key, value <span class="kw">in</span> info.items():
        <span class="fn">print</span>(<span class="st">f"{key}: {value}"</span>)

print_profile(name=<span class="st">"Sarah"</span>, age=22)
print_profile(name=<span class="st">"Ahmed"</span>, age=25, city=<span class="st">"Casablanca"</span>)   <span class="cm"># مرن تماماً</span>


<span class="cm"># الجمع بين معاملات عادية، *args، و**kwargs</span>
<span class="kw">def</span> describe_order(customer, *items, **details):
    <span class="fn">print</span>(<span class="st">f"Customer: {customer}"</span>)
    <span class="fn">print</span>(<span class="st">f"Items: {items}"</span>)
    <span class="fn">print</span>(<span class="st">f"Details: {details}"</span>)

describe_order(<span class="st">"Sarah"</span>, <span class="st">"book"</span>, <span class="st">"pen"</span>, priority=<span class="st">"high"</span>, gift_wrap=<span class="kw">True</span>)`,
    quiz: {
        q: {
            ar: "def f(a, **kwargs, b):\nما مشكلة تعريف هذه الدالة؟",
            en: "def f(a, **kwargs, b):\nWhat is wrong with this function definition?"
        },
        options: {
            ar: [
                "لا مشكلة، التعريف صحيح تماماً",
                "**kwargs يجب أن يكون آخر معامل دائماً، لا يمكن وضع معامل عادي بعده",
                "a يجب أن يكون بعد kwargs",
                "لا يمكن استخدام **kwargs مع معاملات عادية إطلاقاً"
            ],
            en: [
                "No issue, this definition is completely valid",
                "**kwargs must always be the last parameter — a regular parameter can't come after it",
                "a must come after kwargs",
                "**kwargs can never be used with regular parameters at all"
            ]
        },
        correct: 1,
        explanation: {
            ar: "الترتيب الإلزامي في بايثون: المعاملات العادية أولاً، ثم *args إن وُجد، ثم **kwargs في النهاية دائماً — لأنه يجب أن يجمع كل ما تبقّى من وسائط مسمّاة. وضع معامل عادي بعد **kwargs يرمي SyntaxError.",
            en: "Python's mandatory order is: regular parameters first, then *args if present, then **kwargs always last — because it must collect whatever keyword arguments remain. Placing a regular parameter after **kwargs raises a SyntaxError."
        }
    }
},

/* ---------- الدرس 42 ---------- */
{
    title: { ar: "Decorators: تزيين الدوال بسلوك إضافي", en: "Decorators: adding behavior to functions" },
    body: {
        ar: `
<p>تخيّل أن عندك عشرين دالة، وتريد قياس زمن تنفيذ كل واحدة منها لأغراض التصحيح. هل تضيف كود قياس الوقت يدوياً داخل كل دالة؟ هذا تكرار مؤلم. <strong>Decorator</strong> يحلّ هذا: دالة تُغلّف دالة أخرى، تضيف سلوكاً إضافياً حولها (قبل، بعد، أو بدلاً من تنفيذها) دون تعديل كود الدالة الأصلية نفسها إطلاقاً.</p>

<h3>الفكرة: دالة تُرجع دالة</h3>

<p>بما أن الدوال في بايثون قيم (تعلمت هذا في درس lambda)، يمكن لدالة أن تأخذ دالة أخرى كمعامل، وتُرجع دالة جديدة تُغلّفها. هذا بالضبط ما يفعله Decorator: <code>def my_decorator(func):</code> يستقبل الدالة الأصلية، ويُعرِّف دالة داخلية <code>wrapper(*args, **kwargs)</code> تستدعي <code>func</code> الأصلية مع إضافة سلوك قبلها أو بعدها، ثم يُرجع <code>wrapper</code> بدل <code>func</code>.</p>

<h3>تطبيق Decorator بـ @</h3>

<p>بدل استدعاء الآلية يدوياً، بايثون توفّر صيغة مختصرة أنيقة: ضع <code>@my_decorator</code> فوق تعريف أي دالة تريد "تزيينها" مباشرة: <code>@my_decorator\\ndef greet(): ...</code>. هذا يكافئ فعلياً <code>greet = my_decorator(greet)</code>، لكن بصيغة أوضح وأشيع بكثير في الكود الاحترافي.</p>

<h3>لماذا *args و**kwargs ضروريان هنا؟</h3>

<p>الدالة <code>wrapper</code> الداخلية يجب أن تقبل <strong>أي</strong> معاملات قد تحتاجها الدالة الأصلية المُزيَّنة، بغض النظر عن عددها أو أنواعها — لهذا بالضبط استخدمت <code>*args, **kwargs</code> في الدرس السابق، لتمرير كل الوسائط الممكنة لـ <code>func</code> الأصلية دون معرفة توقيعها مسبقاً.</p>

<h3>استخدامات عملية شائعة</h3>

<p>قياس زمن التنفيذ، تسجيل استدعاءات دالة (logging) لأغراض التصحيح، التحقّق من صلاحيات المستخدم قبل تنفيذ دالة حسّاسة، أو تخزين نتائج مؤقتة (caching) لتجنّب إعادة حساب نفس الشيء — كلها أمثلة حقيقية على Decorators في مشاريع بايثون احترافية.</p>

<h3>أخطاء شائعة</h3>

<p>نسيان إرجاع <code>wrapper</code> من الـ decorator نفسه — بدون <code>return wrapper</code>، تصبح الدالة المُزيَّنة <code>None</code> فعلياً. ونسيان استدعاء <code>func(*args, **kwargs)</code> فعلياً داخل <code>wrapper</code> — بدونها، تُضاف السلوكيات الإضافية لكن الدالة الأصلية لا تُنفَّذ أبداً.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>Decorator دالة تُغلّف دالة أخرى بسلوك إضافي دون تعديل كودها الأصلي</li>
    <li>الصيغة <code>@decorator_name</code> فوق تعريف الدالة تطبّقه مباشرة</li>
    <li>تحتاج <code>*args, **kwargs</code> داخل wrapper لدعم أي توقيع دالة أصلية</li>
    <li>استخدامات شائعة: قياس الوقت، التسجيل، التحقّق من الصلاحيات، التخزين المؤقت</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>اكتب decorator باسم <code>log_call</code> يطبع "Calling greet..." قبل تنفيذ أي دالة مُزيَّنة به، وطبّقه على دالة <code>greet(name)</code> باستخدام <code>@log_call</code>. تأكد أن الدالة الأصلية لا تزال تُنفَّذ وتعمل بشكل صحيح.</p>
`,
        en: `<p>A decorator is a function that wraps another function to add behavior around it, without changing its original code. def decorator(func): defines an inner wrapper(*args, **kwargs) that calls func and adds extra behavior, then returns wrapper. Apply it with @decorator_name above a function definition.</p>`
    },
    code: `<span class="cm"># decorator بسيط: يطبع رسالة قبل وبعد تنفيذ الدالة</span>
<span class="kw">def</span> log_call(func):
    <span class="kw">def</span> wrapper(*args, **kwargs):
        <span class="fn">print</span>(<span class="st">f"Calling {func.__name__}..."</span>)
        <span class="kw">result</span> = func(*args, **kwargs)   <span class="cm"># استدعاء الدالة الأصلية فعلياً</span>
        <span class="fn">print</span>(<span class="st">f"{func.__name__} finished"</span>)
        <span class="kw">return</span> result
    <span class="kw">return</span> wrapper


<span class="cm"># تطبيق الـ decorator بصيغة @</span>
<span class="fn">@log_call</span>
<span class="kw">def</span> greet(name):
    <span class="fn">print</span>(<span class="st">f"Hello, {name}"</span>)
    <span class="kw">return</span> <span class="st">f"Greeted {name}"</span>

<span class="kw">result</span> = greet(<span class="st">"Sarah"</span>)
<span class="fn">print</span>(<span class="st">f"Returned: {result}"</span>)


<span class="cm"># decorator عملي: قياس زمن التنفيذ</span>
<span class="kw">import</span> time

<span class="kw">def</span> measure_time(func):
    <span class="kw">def</span> wrapper(*args, **kwargs):
        <span class="kw">start</span> = time.time()
        <span class="kw">result</span> = func(*args, **kwargs)
        <span class="kw">elapsed</span> = time.time() - start
        <span class="fn">print</span>(<span class="st">f"{func.__name__} took {elapsed:.4f}s"</span>)
        <span class="kw">return</span> result
    <span class="kw">return</span> wrapper

<span class="fn">@measure_time</span>
<span class="kw">def</span> slow_sum(n):
    <span class="kw">return</span> <span class="fn">sum</span>(<span class="fn">range</span>(n))

slow_sum(1000000)`,
    quiz: {
        q: {
            ar: "لماذا تستقبل الدالة wrapper داخل الـ decorator المعاملات *args, **kwargs بدل معاملات محدّدة؟",
            en: "Why does the wrapper function inside a decorator accept *args, **kwargs instead of specific parameters?"
        },
        options: {
            ar: [
                "لأن *args, **kwargs أسرع في التنفيذ",
                "ليتمكّن الـ decorator من العمل مع أي دالة، مهما كان عدد أو نوع معاملاتها",
                "هذا إلزامي في بايثون لكل دالة داخلية",
                "لا سبب حقيقي، مجرّد اصطلاح شائع بلا فائدة عملية"
            ],
            en: [
                "Because *args, **kwargs execute faster",
                "So the decorator can work with any function, regardless of how many or what kind of parameters it has",
                "This is mandatory in Python for every inner function",
                "No real reason, just a common convention with no practical benefit"
            ]
        },
        correct: 1,
        explanation: {
            ar: "decorator عام يجب أن يعمل مع دوال مختلفة تماماً في توقيعها: بعضها بلا معاملات، بعضها بعشرة. *args, **kwargs يجمعان أي وسائط مُمرَّرة مهما كان عددها ونوعها، ويمرّرانها كاملة لـ func الأصلية دون الحاجة لمعرفة توقيعها الدقيق مسبقاً.",
            en: "A general-purpose decorator must work with functions that have completely different signatures — some with no parameters, some with ten. *args, **kwargs collect whatever arguments are passed, regardless of count or type, and forward them all to the original func without needing to know its exact signature in advance."
        }
    }
},

/* ---------- الدرس 43 ---------- */
{
    title: { ar: "Generators: القيم عند الطلب", en: "Generators: values on demand" },
    body: {
        ar: `
<p>تخيّل أنك تريد معالجة مليار رقم. لو بنيت قائمة كاملة بها بـ <code>[x for x in range(1000000000)]</code>، ستستهلك ذاكرة هائلة قبل حتى أن تبدأ المعالجة الفعلية. <strong>Generator</strong> يحلّ هذا: بدل حساب كل القيم دفعة واحدة وتخزينها في الذاكرة، يُنتج قيمة واحدة <strong>عند الطلب فقط</strong>، كلما احتجتها، دون تخزين البقية إطلاقاً.</p>

<h3>الكلمة المفتاحية yield</h3>

<p>دالة عادية تستخدم <code>return</code> لإرجاع قيمة واحدة ثم تنتهي كلياً. دالة Generator تستخدم <code>yield</code> بدلاً منها: كل مرة تصل الدالة لـ <code>yield value</code>، "تُجمَّد" الدالة في مكانها وتُرجع تلك القيمة، لكنها <strong>تتذكّر</strong> مكانها بالضبط، جاهزة لمتابعة التنفيذ من نفس النقطة عند الطلب التالي.</p>

<h3>استهلاك Generator</h3>

<p>استدعاء دالة تحتوي <code>yield</code> لا يُنفّذها فوراً — يُنشئ كائن generator فقط. القيم تُستخرَج فعلياً بالتكرار عليه بحلقة <code>for</code>، أو باستدعاء <code>next()</code> يدوياً مرة تلو الأخرى، كل استدعاء يُكمل التنفيذ حتى <code>yield</code> التالية.</p>

<h3>لماذا Generators موفّرة للذاكرة؟</h3>

<p>القائمة العادية تحسب <strong>كل</strong> القيم وتخزّنها في الذاكرة قبل أن تستخدم أياً منها. Generator يحسب قيمة واحدة فقط، يُنتجها، وينتظر — لا يخزّن شيئاً آخر أبداً. لملف ضخم أو تسلسل لا نهائي منطقياً، هذا الفرق حاسم: قائمة كاملة قد تُسقط برنامجك بنفاد الذاكرة، بينما generator يعمل بسلاسة مهما طال التسلسل.</p>

<h3>Generator Expression: نسخة مختصرة</h3>

<p>مثل تحويل List Comprehension بسيط لـ generator، فقط استبدل الأقواس المربّعة بأقواس هلالية: <code>(x**2 for x in range(1000000))</code> يُنشئ generator بدل قائمة كاملة فوراً — نفس منطق الكسل (lazy evaluation) بصيغة مختصرة جداً.</p>

<h3>أخطاء شائعة</h3>

<p>محاولة استخدام generator أكثر من مرة — بمجرد استهلاك كل قيمه (بحلقة for كاملة مثلاً)، ينضب تماماً ولا يُعيد أي قيمة عند محاولة التكرار عليه مجدداً؛ يجب إنشاء generator جديد لإعادة الاستخدام.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>Generator يُنتج قيماً عند الطلب فقط، بدل حساب كل شيء دفعة واحدة في الذاكرة</li>
    <li><code>yield</code> "يُجمِّد" الدالة ويُرجع قيمة، متذكّراً مكانه لمتابعة التنفيذ لاحقاً</li>
    <li>يُستهلَك بحلقة <code>for</code> أو <code>next()</code>، وينضب بمجرد استخدامه بالكامل مرة واحدة</li>
    <li>Generator Expression: <code>(expr for item in iterable)</code> — نسخة مختصرة كسولة</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>اكتب دالة generator باسم <code>even_numbers(limit)</code> تُنتج الأعداد الزوجية من 0 حتى limit واحداً تلو الآخر باستخدام <code>yield</code>. استهلكها بحلقة <code>for</code> واطبع كل قيمة.</p>
`,
        en: `<p>A generator produces values one at a time, on demand, instead of computing everything upfront in memory. yield freezes the function at that point and returns a value, resuming from there on the next request. Consume it with a for loop or next(); once fully consumed, it's exhausted.</p>`
    },
    code: `<span class="cm"># دالة عادية: تحسب كل القيم دفعة واحدة</span>
<span class="kw">def</span> square_list(n):
    <span class="kw">result</span> = []
    <span class="kw">for</span> i <span class="kw">in</span> <span class="fn">range</span>(n):
        result.append(i**2)
    <span class="kw">return</span> result   <span class="cm"># كل القيم مخزَّنة في الذاكرة دفعة واحدة</span>


<span class="cm"># دالة generator: تُنتج قيمة واحدة في كل مرة</span>
<span class="kw">def</span> square_generator(n):
    <span class="kw">for</span> i <span class="kw">in</span> <span class="fn">range</span>(n):
        <span class="kw">yield</span> i**2   <span class="cm"># تُجمَّد هنا، تنتظر الطلب التالي</span>


<span class="cm"># الاستدعاء وحده لا ينفّذ شيئاً — يُنشئ كائن generator فقط</span>
<span class="kw">gen</span> = square_generator(5)
<span class="fn">print</span>(<span class="fn">type</span>(gen))   <span class="cm"># &lt;class 'generator'&gt;</span>

<span class="cm"># الاستهلاك بحلقة for</span>
<span class="kw">for</span> value <span class="kw">in</span> gen:
    <span class="fn">print</span>(value)


<span class="cm"># الاستهلاك اليدوي بـ next()</span>
<span class="kw">gen2</span> = square_generator(3)
<span class="fn">print</span>(<span class="fn">next</span>(gen2))   <span class="cm"># 0</span>
<span class="fn">print</span>(<span class="fn">next</span>(gen2))   <span class="cm"># 1</span>
<span class="fn">print</span>(<span class="fn">next</span>(gen2))   <span class="cm"># 4</span>


<span class="cm"># Generator Expression — نسخة مختصرة من list comprehension</span>
<span class="kw">squares_gen</span> = (x**2 <span class="kw">for</span> x <span class="kw">in</span> <span class="fn">range</span>(5))
<span class="fn">print</span>(<span class="fn">list</span>(squares_gen))   <span class="cm"># [0, 1, 4, 9, 16]</span>`,
    quiz: {
        q: {
            ar: "ما الفائدة الأساسية من استخدام generator بدل قائمة عادية لبيانات ضخمة جداً؟",
            en: "What is the main benefit of using a generator instead of a regular list for very large data?"
        },
        options: {
            ar: [
                "generator يُنتج قيماً بترتيب عشوائي دائماً",
                "generator يُنتج قيمة واحدة عند الطلب فقط، دون تخزين كل القيم في الذاكرة دفعة واحدة",
                "generator أسرع من القائمة في كل الحالات بلا استثناء",
                "لا فرق فعلي في الاستخدام العملي"
            ],
            en: [
                "A generator always produces values in random order",
                "A generator produces one value at a time on demand, without storing all values in memory at once",
                "A generator is always faster than a list in every case with no exceptions",
                "There's no real practical difference"
            ]
        },
        correct: 1,
        explanation: {
            ar: "القائمة العادية تحسب وتخزّن كل القيم في الذاكرة فوراً، حتى لو استخدمت واحدة منها فقط. generator يحسب قيمة واحدة عند الحاجة الفعلية إليها، مما يجعله موفّراً جداً للذاكرة مع بيانات ضخمة أو تسلسلات طويلة جداً.",
            en: "A regular list computes and stores every value in memory immediately, even if you only end up using one. A generator computes a single value only when actually needed, making it far more memory-efficient for huge data or very long sequences."
        }
    }
},

/* ---------- الدرس 44 ---------- */
{
    title: { ar: "PEP 8: كتابة كود بايثون نظيف", en: "PEP 8: writing clean Python code" },
    body: {
        ar: `
<p>الكود الذي يعمل ليس كافياً وحده — الكود الاحترافي يجب أن يكون <strong>مقروءاً</strong> أيضاً، لك ولأي شخص آخر يقرأه لاحقاً. <strong>PEP 8</strong> هو دليل الأسلوب الرسمي لكتابة بايثون، يحدّد معايير موحّدة للتنسيق والتسمية يتّبعها المجتمع العالمي بأكمله تقريباً — مما يجعل أي كود بايثون احترافي يبدو مألوفاً لأي مبرمج آخر، بغض النظر عمّن كتبه.</p>

<h3>تسمية المتغيرات والدوال</h3>

<p>الاصطلاح المعياري: <code>snake_case</code> للمتغيّرات والدوال (كلمات صغيرة مفصولة بشرطة سفلية: <code>user_name</code>, <code>calculate_total</code>)، و<code>PascalCase</code> لأسماء الأصناف (كل كلمة تبدأ بحرف كبير، بلا فواصل: <code>BankAccount</code>). أسماء واضحة ووصفية دائماً — <code>user_age</code> أفضل بكثير من <code>ua</code> أو <code>x</code>.</p>

<h3>المسافات والتنسيق</h3>

<p>مسافة واحدة بعد الفاصلة: <code>func(a, b, c)</code> لا <code>func(a,b,c)</code>. مسافة حول عوامل التعيين والمقارنة: <code>x = 5</code> لا <code>x=5</code>. أربع مسافات للمسافة البادئة (indentation) دائماً، لا Tab وMerge بينهما في نفس الملف. أقصى طول سطر مُوصى به 79 حرفاً تقريباً، لسهولة القراءة على شاشات مختلفة.</p>

<h3>الأسطر الفارغة للتنظيم البصري</h3>

<p>سطران فارغان بين تعريفات الدوال والأصناف على مستوى الملف، وسطر فارغ واحد بين methods داخل صنف — هذا يفصل بصرياً بين الأجزاء المنطقية المختلفة، تماماً كالفقرات في نصّ مكتوب.</p>

<h3>لماذا PEP 8 مهم عملياً؟</h3>

<p>في أي فريق برمجي حقيقي، عشرات المبرمجين يقرؤون كود بعضهم يومياً. اتباع معيار موحّد يعني أن أي شخص يفتح ملفاً جديداً يفهمه فوراً دون التكيّف مع أسلوب كل مبرمج على حدة. أدوات مثل <code>black</code> أو <code>flake8</code> تُنسّق أو تتحقّق من التزام كودك بـ PEP 8 تلقائياً في المشاريع الاحترافية.</p>

<h3>أخطاء شائعة</h3>

<p>تسمية متغيّرات بحروف مفردة غامضة (<code>x</code>, <code>y</code>, <code>tmp</code>) في كود ليس لغرض رياضي واضح. وخلط أساليب تسمية مختلفة في نفس المشروع (بعض الدوال <code>camelCase</code> وبعضها <code>snake_case</code>) — التزم بأسلوب واحد ثابت طوال المشروع.</p>

<h3>لخّص ما تعلمته</h3>

<ul>
    <li>PEP 8 دليل الأسلوب الرسمي لبايثون، متّبع عالمياً في الكود الاحترافي</li>
    <li><code>snake_case</code> للمتغيّرات والدوال، <code>PascalCase</code> لأسماء الأصناف</li>
    <li>مسافة بعد الفواصل، حول عوامل التعيين، وأربع مسافات للمسافة البادئة</li>
    <li>أسطر فارغة تفصل الدوال والأصناف بصرياً، وأسماء واضحة ووصفية دائماً</li>
</ul>

<h3>تمرين تطبيقي</h3>

<p>خذ هذا الكود غير المنسَّق: <code>def calc(a,b):\\n  x=a+b\\n  return x</code> وأعد كتابته وفق PEP 8: اسم دالة أوضح، مسافات صحيحة، ومسافة بادئة موحّدة بأربع مسافات.</p>
`,
        en: `<p>PEP 8 is Python's official style guide: snake_case for variables/functions, PascalCase for classes, a space after commas and around operators, four-space indentation, and blank lines separating functions/classes visually — the shared standard that makes any professional Python code feel familiar to any other Python programmer.</p>`
    },
    code: `<span class="cm"># قبل PEP 8 — يعمل، لكنه صعب القراءة</span>
<span class="cm"># def calc(a,b):</span>
<span class="cm">#   x=a+b</span>
<span class="cm">#   return x</span>


<span class="cm"># بعد PEP 8 — نفس المنطق، أوضح بكثير</span>
<span class="kw">def</span> calculate_total(first_number, second_number):
    <span class="kw">total</span> = first_number + second_number
    <span class="kw">return</span> total


<span class="cm"># snake_case للمتغيرات والدوال</span>
<span class="kw">user_name</span> = <span class="st">"Sarah"</span>
<span class="kw">total_score</span> = 95

<span class="kw">def</span> get_full_name(first_name, last_name):
    <span class="kw">return</span> <span class="st">f"{first_name} {last_name}"</span>


<span class="cm"># PascalCase لأسماء الأصناف</span>
<span class="kw">class</span> BankAccount:
    <span class="kw">def</span> __init__(self, owner):
        self.owner = owner


<span class="cm"># مسافات صحيحة حول العوامل والفواصل</span>
<span class="kw">numbers</span> = [1, 2, 3, 4, 5]
<span class="kw">average</span> = <span class="fn">sum</span>(numbers) / <span class="fn">len</span>(numbers)


<span class="cm"># سطران فارغان يفصلان تعريفات مستقلة — كما في هذا الملف نفسه</span>
<span class="kw">def</span> first_function():
    <span class="fn">print</span>(<span class="st">"First"</span>)


<span class="kw">def</span> second_function():
    <span class="fn">print</span>(<span class="st">"Second"</span>)`,
    quiz: {
        q: {
            ar: "أي اسم متغيّر يتبع اصطلاح snake_case الموصى به في PEP 8؟",
            en: "Which variable name follows the snake_case convention recommended by PEP 8?"
        },
        options: {
            ar: ["userAge", "UserAge", "user_age", "USERAGE"],
            en: ["userAge", "UserAge", "user_age", "USERAGE"]
        },
        correct: 2,
        explanation: {
            ar: "snake_case يعني حروفاً صغيرة بالكامل مع فصل الكلمات بشرطة سفلية: user_age. userAge بصيغة camelCase (شائعة في JavaScript)، وUserAge بصيغة PascalCase (تُستخدم لأسماء الأصناف فقط في بايثون)، وUSERAGE أحرف كبيرة بلا فصل، غير مقروء.",
            en: "snake_case means fully lowercase with words separated by underscores: user_age. userAge is camelCase (common in JavaScript), UserAge is PascalCase (reserved for class names in Python), and USERAGE is all-caps with no separation, which is hard to read."
        }
    }
},

/* ---------- الدرس 45 — مشروع ---------- */
{
    title: { ar: "المشروع النهائي: متتبّع المصاريف الشخصية", en: "Final project: personal expense tracker" },
    body: {
        ar: `
<p>وصلت للمشروع الأخير في مسار بايثون، والذي يجمع <strong>كل شيء</strong> تعلّمته من الدرس الأول حتى الآن: المتغيّرات والحلقات والدوال، القوائم والقواميس، الأصناف والوراثة، الملفات وJSON، معالجة الأخطاء، Decorators، Generators، وكتابة كود نظيف وفق PEP 8. ستبني متتبّع مصاريف شخصية كامل، بجودة مقاربة لمشروع حقيقي.</p>

<h3>البنية العامة: أصناف متعاونة ببيانات دائمة</h3>

<p>صنف <code>Expense</code> يمثّل مصروفاً واحداً (المبلغ، الفئة، الوصف)، وصنف <code>ExpenseTracker</code> يدير قائمة المصاريف كاملة، يحفظها ويحمّلها من JSON — تماماً كنمط مشروع مدير المهام، لكن بأصناف حقيقية بدل قواميس مباشرة.</p>

<h3>Decorator للتسجيل التلقائي</h3>

<p>طُبِّق <code>@log_action</code> (من درس Decorators) على method إضافة المصروف، فيُسجَّل تلقائياً كل عملية إضافة في الطرفية دون تكرار كود الطباعة داخل كل method على حدة — استخدام عملي مباشر لما تعلمته.</p>

<h3>Generator لتصفية كسولة</h3>

<p>method باسم <code>expenses_by_category(category)</code> تستخدم <code>yield</code> لإنتاج المصاريف المطابقة لفئة معيّنة واحداً تلو الآخر، بدل بناء قائمة كاملة فوراً — مفيد جداً لو كان عدد المصاريف ضخماً في تطبيق حقيقي.</p>

<h3>معالجة الأخطاء والتحقّق</h3>

<p>إضافة مصروف بمبلغ سالب ترمي <code>ValueError</code> عبر <code>raise</code> (من درس التحقّق المسبق)، وتحميل ملف JSON غير موجود عند أول تشغيل يُعالَج بأناقة بـ <code>try/except FileNotFoundError</code> — بالضبط كما تعلّمت في المستوى الخامس.</p>

<h3>ماذا يعني إكمالك لهذا المشروع؟</h3>

<p>لقد بنيت الآن برنامجاً متكاملاً بمعايير احترافية حقيقية: بيانات دائمة، تصميم كائني منظّم، معالجة أخطاء متوقّعة، وكود نظيف قابل للقراءة. هذه بالضبط المهارات التي تفصل بين "أعرف بايثون" و"أستطيع بناء برامج حقيقية بها".</p>

<h3>تحديات للتوسيع (اختيارية، لمن يريد الاستمرار)</h3>

<ul>
    <li>أضف تقريراً شهرياً يجمع المصاريف حسب الفئة باستخدام Dictionary Comprehension</li>
    <li>صدّر التقرير كملف CSV بدل JSON فقط</li>
    <li>أضف صنف <code>Budget</code> يرث سلوكاً من <code>ExpenseTracker</code> ويضيف حدّاً أقصى شهرياً لكل فئة</li>
</ul>

<h3>ماذا أنجزت في مسار بايثون كاملاً؟</h3>

<ul>
    <li>أتقنت أساسيات اللغة: المتغيّرات، الأنواع، الشروط، والحلقات</li>
    <li>نظّمت البيانات بهياكل مناسبة: قوائم، Tuples، Sets، وقواميس</li>
    <li>هيكلت الكود بدوال قابلة لإعادة الاستخدام، بمعاملات مرنة وقيم مُرجَعة واضحة</li>
    <li>تعاملت مع الملفات والبيانات الدائمة بأمان، وعالجت الأخطاء بأناقة بدل الانهيار</li>
    <li>صمّمت أصنافاً حقيقية بالوراثة وEncapsulation وMagic Methods</li>
    <li>استخدمت أدوات احترافية: الوحدات، pip، Decorators، وGenerators</li>
    <li>وكتبت كوداً نظيفاً واضحاً وفق معايير PEP 8 العالمية</li>
</ul>

<p><strong>مبروك!</strong> أكملت مسار بايثون بالكامل من الصفر حتى الاحتراف — 45 درساً و6 مشاريع حقيقية. الخطوة التالية في رحلتك: اختر مساراً جديداً في كودنا (تطوير الويب، تحليل البيانات، أو غيره)، أو ابدأ ببناء مشروعك الخاص بأفكارك أنت.</p>
`,
        en: `<p>The capstone project combines everything from this path: Expense and ExpenseTracker classes, JSON persistence, a @log_action decorator, a generator for lazy filtering by category, raise for validation, and try/except for graceful first-run handling — a complete, professionally-structured program built entirely from what you learned.</p>`
    },
    code: `<span class="cm"># ============================================</span>
<span class="cm"># متتبّع المصاريف الشخصية</span>
<span class="cm"># ============================================</span>
<span class="kw">import</span> json


<span class="kw">def</span> log_action(func):
    <span class="kw">def</span> wrapper(*args, **kwargs):
        <span class="kw">result</span> = func(*args, **kwargs)
        <span class="fn">print</span>(<span class="st">f"[LOG] {func.__name__} executed"</span>)
        <span class="kw">return</span> result
    <span class="kw">return</span> wrapper


<span class="kw">class</span> Expense:
    <span class="kw">def</span> __init__(self, amount, category, description):
        <span class="kw">if</span> amount <= 0:
            <span class="kw">raise</span> <span class="fn">ValueError</span>(<span class="st">"Amount must be positive"</span>)
        self.amount = amount
        self.category = category
        self.description = description

    <span class="kw">def</span> __str__(self):
        <span class="kw">return</span> <span class="st">f"{self.category}: \${self.amount:.2f} — {self.description}"</span>

    <span class="kw">def</span> to_dict(self):
        <span class="kw">return</span> {<span class="st">"amount"</span>: self.amount, <span class="st">"category"</span>: self.category, <span class="st">"description"</span>: self.description}


<span class="kw">class</span> ExpenseTracker:
    <span class="kw">def</span> __init__(self, filename=<span class="st">"expenses.json"</span>):
        self.filename = filename
        self.expenses = self._load()

    <span class="kw">def</span> _load(self):
        <span class="kw">try</span>:
            <span class="kw">with</span> <span class="fn">open</span>(self.filename, <span class="st">"r"</span>) <span class="kw">as</span> file:
                <span class="kw">data</span> = json.load(file)
                <span class="kw">return</span> [Expense(**item) <span class="kw">for</span> item <span class="kw">in</span> data]
        <span class="kw">except</span> <span class="fn">FileNotFoundError</span>:
            <span class="kw">return</span> []   <span class="cm"># أول تشغيل — طبيعي تماماً</span>

    <span class="kw">def</span> _save(self):
        <span class="kw">with</span> <span class="fn">open</span>(self.filename, <span class="st">"w"</span>) <span class="kw">as</span> file:
            json.dump([e.to_dict() <span class="kw">for</span> e <span class="kw">in</span> self.expenses], file)

    <span class="fn">@log_action</span>
    <span class="kw">def</span> add(self, amount, category, description):
        self.expenses.append(Expense(amount, category, description))
        self._save()

    <span class="cm"># generator: تصفية كسولة حسب الفئة</span>
    <span class="kw">def</span> expenses_by_category(self, category):
        <span class="kw">for</span> expense <span class="kw">in</span> self.expenses:
            <span class="kw">if</span> expense.category == category:
                <span class="kw">yield</span> expense

    <span class="kw">def</span> __len__(self):
        <span class="kw">return</span> <span class="fn">len</span>(self.expenses)


<span class="kw">tracker</span> = ExpenseTracker()
tracker.add(50, <span class="st">"food"</span>, <span class="st">"Groceries"</span>)
tracker.add(20, <span class="st">"transport"</span>, <span class="st">"Bus ticket"</span>)

<span class="fn">print</span>(<span class="st">f"Total expenses: {len(tracker)}"</span>)
<span class="kw">for</span> expense <span class="kw">in</span> tracker.expenses_by_category(<span class="st">"food"</span>):
    <span class="fn">print</span>(expense)`,
    quiz: {
        q: {
            ar: "لماذا استُخدمت raise ValueError داخل __init__ في صنف Expense؟",
            en: "Why is raise ValueError used inside __init__ in the Expense class?"
        },
        options: {
            ar: [
                "خطأ في التصميم، __init__ لا يجب أن يرمي أخطاء",
                "لمنع إنشاء كائن Expense بمبلغ غير منطقي (سالب أو صفر) منذ اللحظة الأولى",
                "raise إلزامية في كل __init__ بلا استثناء",
                "لتسريع تنفيذ الدالة"
            ],
            en: [
                "A design mistake — __init__ should never raise errors",
                "To prevent creating an Expense object with an illogical amount (negative or zero) from the very first moment",
                "raise is mandatory in every __init__ with no exception",
                "To make the function execute faster"
            ]
        },
        correct: 1,
        explanation: {
            ar: "التحقّق داخل __init__ يضمن أنه لا يمكن أبداً إنشاء كائن Expense في حالة غير منطقية (مبلغ سالب أو صفري) — يفشل الإنشاء فوراً برسالة واضحة بدل السماح ببيانات فاسدة تنتشر بصمت في بقية البرنامج، وهذا امتداد مباشر لمبدأ raise من مستوى سابق.",
            en: "Validating inside __init__ guarantees an Expense object can never exist in an illogical state (a negative or zero amount) — creation fails immediately with a clear message instead of letting corrupt data silently spread through the rest of the program, a direct extension of the raise principle from an earlier level."
        }
    }
}





